insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "ba5f8905-1f7e-4d87-b4b0-c345e93849b4", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 6, "content": "Eric Porter (12:02): Yeah, so it's been awesome. And the whole time I've worked with the product department as well, which is still run by the same guy, Michael Brown, and he's amazing. So we've worked together to, we will go to meetings and I'll say, I think it would be great to have a bike like this, and then we make that bike. So it's really cool and it helps drive the product line and make the product better. It's also keeping me on the bikes that I want to ride, and it's been pretty amazing to be a part of that as well as just seeing where the brand has come from then until now.\n\nCole Heilborn (12:38): Yeah, yeah, no kidding. So you were kind of making aspirational videos, I feel like in the early days of YouTube, but you weren't publishing them on YouTube at that point. Where were those going?\n\nEric Porter (12:53): Some of them were on YouTube, but it was at that point, Vimeo was a bigger one. And then it was a time when all of the media wanted to have their own players, (13:03): So Vital and Pink Bike and all of the media outlets, they had their own players. So I mean there were fights over who gets the video and what Media Outlet gets to host it and Bike Mag as well, everyone wanted their own player and then they realized that they're never going to be able to monetize that the way anyone else is, and they're paying all these hosting fees. And so it's somewhere in there. YouTube became the place to post things, I think because they were able to look at it. It's their own TV network. So it's the first place that's kind of a win-win for everybody to where the advertisers can target exactly who they want to see their video. YouTube gets the ad revenue and splits it with the creator. So they're making money. The person that made the video gets their cut of the revenue and then the viewer gets unlimited free videos uploaded all the time,\n\nCole Heilborn (14:03): Maybe too many videos,", "token_estimate": 480, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "12:02", "end_timestamp": "14:03", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "4718f379-fbff-4b48-bbdf-5e50905728e7", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 7, "content": "Eric Porter (14:04): Maybe too many, but that's only something that's happened in the last few years really. And I didn't even get in on a personal level until about a year and a half ago. And it's the kind of thing where everything I did up until then was originally D-V-D-V-H-S, that sort of thing. And then it was hosted by the company, wherever we'd make the video, and then it was Diamondbacks video and they would host it wherever they host it. And then just more recently now, it's shifted to where the athletes are. I mean, brands are building their own pages too, which is good, but the athletes are treating it as another. I mean, I just look at it as another media outlet.\n\nCole Heilborn (14:51): Did you decide to jump into YouTube a year and a half ago, and did you have any hesitations to doing so?", "token_estimate": 203, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "14:04", "end_timestamp": "14:51", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "1d28207b-a992-4680-85ce-7d1fbf6fd13a", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 8, "content": "Eric Porter (14:58): I actually had a lot of hesitation with it. For one, it's a lot of work if you want to do it right and if you want to actually have it be successful. And second of all, I saw that I'm not a personal fan of vlogs and someone holding a camera and talking for 10, 20, 30, 40 minutes and saying everything they're doing. And I've hated that part of Twitter and Instagram and everything. I think it kind of ruins your heroes a little bit. I don't want to see Sean Palmer making coffee. I just want to see him winning. So I think, like you said earlier, there's too much information out there. And so I didn't want to just add to that and at the same time create a lot of work that was unnecessary and it was working great, creating stuff with the brands that I work with for their channels. And we didn't even look at it as building channels. It was just putting out videos that people would watch. So then Bryce Winker, who was the marketing manager for Diamondback a few years ago, he was a fan of Seth from Seth's, spike Hacks, probably the biggest or second biggest personal YouTube channel in mountain biking. And at first I didn't understand it at all. Seth, he's a really good rider, but he would never be a professional rider (16:32): At that level, but he found a way to tell stories and inspire people to go mountain biking, and he's brought a ton of people into the sport. So I ended up getting to be really good friends with them through being teammates and doing stuff together and learning more about it. And the more I looked into it, this YouTube was where people were going to get their information and going to not only learn how to do something, which is if you need to do anything, you YouTube it now so you can watch a video of how to do that skill, whatever, but also for their entertainment. So they're going there instead of TV instead of any of these other places because they have it everywhere with them on their phone and it's free. And the other thing that I realized is it's the personal connection. So they're following people on YouTube because they want to feel like they're hanging out with them and going for a ride with them and that sort of thing. So it's really a different experience from watching an anthill video. That's the craziest cinematography and riding ever. And those are unreal to watch, (17:40): But they're looking for a different experience. You see that a few times, and I grew up watching videos over and over, but now they want to be along for the ride,", "token_estimate": 632, "speakers": ["Eric Porter"], "start_timestamp": "14:58", "end_timestamp": "14:58", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "ae75b528-6cfc-44b8-beb1-ea3e324faa6e", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 9, "content": "Speaker 3 (17:51): And\n\nEric Porter (17:52): So that's what they're getting out of YouTube. So it took me a few years to wrap my head around it and understand how I could be a part of that. And like I said earlier, just looking at it as another outlet. So people that kids call me a YouTuber and that's fine because that's the highest form of praise from them to a kid. A YouTuber is the highest celebrity.\n\nCole Heilborn (18:18): Right. That's like being an actor.\n\nEric Porter (18:20): Yeah, totally. And the way I look at it is that that's another outlet. So Instagram is another outlet and magazines are another outlet, and TV is another outlet, and my job is to be in all those channels, whereas Seth might focus on YouTube exclusively. I still try to focus on YouTube, but focus on other stuff too, because I think it's all important and you have different audiences in different locations basically. So if I'm in Bike Magazine, mountain Bike Action, mountain Flyer or whatever, that's hitting a certain customer and consumer of bikes. And if I'm on YouTube, that's hitting a totally different one and they're probably not overlapping that much.\n\nCole Heilborn (19:09): Yeah, that leads me to my next question. You brought up the difference between what you and Seth are doing versus what an Anthill films production is like. Where did those different films or videos, who are those four, and do you think that we're going to see less and less of those big budget send it films?", "token_estimate": 371, "speakers": ["Speaker 3", "Eric Porter", "Cole Heilborn"], "start_timestamp": "17:51", "end_timestamp": "19:09", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "7b8e1091-2221-4345-bec9-3ada705d4a39", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 10, "content": "Eric Porter (19:34): I already are seeing a lot, which I think is a bummer. I love 'em and I think they're amazing, and it's the coolest thing ever to be a part of those because it's such a high production value and just insane stuff that inspires people also. And people talk about it for years. I mean, video parts are forever, whereas YouTube is forever too, but it's more like a moment in time (19:58): And some stuff, some of them last a lot longer than others, but I do think it's really special to put a year into a project. And my teammate, Mike Hopkins on Diamondback, that's what he does best, is really high production value stuff. So before he was on Diamondback, he did Lifecycles, which I think he spent two years just on that project and probably didn't work on much else when it came out. People still talk about the lifecycles video 10 years and it came out 10 years ago. And so I think those do have an amazing impact, and I hate to see them. I don't think they'll ever go away, but they're definitely changing and there's not as many coming out as there used to be. It used to be at Interbike, a bunch of videos would come out that people on all year, and it was incredible. (20:51): And I love that from BMX and from snowboarding and all the skiing and all these other sports as well, seeing a project someone's worked on for a long time, and Mike has been able to do that with Diamondback, with the Dream Ride series and skids and siblings, and he does stuff that I'm totally jealous of. I wish I could be a part of it, but at the same time, with the way that I run my program and having kids and family and stuff, I can't commit two months to one project and being gone the whole time and working just on that. So it's cool. I just hope that people continue doing that because we need the really high level stuff and we also need the more consumable daily, weekly, monthly stuff too. So I think it's good to hit it from all the angles.\n\nCole Heilborn (21:44): Sure. So what's the experience been like? You're year and a half into making YouTube videos. What's it been like?", "token_estimate": 524, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "19:34", "end_timestamp": "21:44", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "4c422498-2f97-4bae-a923-445532ca8bf0", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 11, "content": "Eric Porter (21:53): It's the hardest I've ever worked, and probably least I've slept, but it's also I think the most rewarding seeing videos reach out, and you can read it in the comments that how much it inspires people, which is incredible. I mean, every video, there's people saying that this got them into mountain biking or this got them back into mountain biking or that it inspires them. I do stuff with my kids sometimes and people saying that it's helped them be a better dad or aspire to be when they are a dad to be like this. And so it's been a way that I can put positivity into the world, show something that maybe you won't have a backyard like this, but you can have neighborhood jumps or you can even just be good to each other. And it's been a really cool way to put that out into the world.\n\nCole Heilborn (22:53): Yeah. How does that feel when you have, I don't know, a young kid or even a college kid or adult come up to you and say like, man, you've totally motivated me or inspired me to get back on the bike or start getting on the bike? How does that feel?\n\nEric Porter (23:10): Oh, it's amazing. I mean, we all know that's a life-changing thing. When you find a sport that you love and you're able to go do that and get out of the real world of school or work or whatever and go ride a bike, it's the best feeling in the world. So it's really cool to know that I'm positively impacting people's lives and really helping make their life better through inspiring them to get out and do something and try hard and work hard and create what you dream up.\n\nCole Heilborn (23:48): What do you think stops people from wanting to get into the sport? What are some of the biggest roadblocks?", "token_estimate": 428, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "21:53", "end_timestamp": "23:48", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "de29ac48-8618-4f4d-b6d1-2ade5297529c", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 12, "content": "Eric Porter (23:57): There's a lot of 'em. I mean, it's not cheap. It better bikes are getting cheaper than ever before, but it's still not cheap. And then not everybody has access to trails either. I was really lucky where I grew up and where I live now that we can ride trails from the house or a really short drive to different trails, but there's a lot of places. I mean, if you live in a big city, how are you ever going to get out of that city? I mean, I know as a parent, even trying to sometimes drive 20 minutes to Park City to go do something, it's a big commitment on my part to do something for the kids. And so I totally get it when parents are working all the time and there's a teenage kid that there's no trails close. They've got to commit an entire day to driving them somewhere else. It's tough. Creating more trails in urban centers is huge. I'm even trying to do that here with, I'm president of Wasatch Trails Foundation as well, which is our local trail advocacy group, and we didn't have any jumps that were public or a public pump track in this valley. (25:13): And Utah has grants available for that. So our group filed for a grant and built the first pump track and flow trails, jump trails here in this community. And it's done a ton for all of the kids around here, created a place that they can ride from their house to do that. So I think getting more people into trail advocacy and creating more trail and ride centers close to urban communities will help a lot.\n\nCole Heilborn (25:41): Yeah, it's amazing to see how many organizations around the country are doing just that.\n\nSpeaker 3 (25:48): Yeah,\n\nCole Heilborn (25:49): I mean, it's kind of taken off. The sport has really grown, I feel like in the last few years.", "token_estimate": 438, "speakers": ["Eric Porter", "Cole Heilborn", "Speaker 3"], "start_timestamp": "23:57", "end_timestamp": "25:49", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "1e142c35-93ac-4ac9-8b87-55c0c4093556", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 13, "content": "Eric Porter (25:55): Yeah, absolutely. Even before this recent growth with COVID, it has been growing and getting bigger every single year. And part of it's the bikes getting better. Part of it's, for some reason, mountain biking is cool now where it wasn't cool for a long time, but now it's at a point where all of the professional athletes in the cool sports, skiing, snowboarding, skateboarding, football, baseball, those guys are all riding mountain bikes now, whereas they would never be caught dead on a mountain bike 10 years ago or whatever. It just wasn't cool for whatever, who knows why. But as a sport, we've done a good job of showing it to the world and making it something that people want to do now.\n\nCole Heilborn (26:51): And that's got to be weird for you. Looking back at being the only kid in high school riding a mountain bike to now being a name out there that a lot of people recognize leaving the charge to getting more people into the sport, that's got to be a strange transition.\n\nEric Porter (27:06): Yeah, absolutely. I was never one of the cool kids in school, and I never had anyone that could relate to what I was doing at all. So my best friends were outside of school in the sports that I did that I would also ride bikes with or do that sort of thing. And looking back, I love it because it kind of created me into who I am and how I feel about things and trying to make it things more inclusive for people and giving people a place to go to escape from the regular life. But I do wonder what it's, I mean, Nica and the whole high school team, it's a huge thing in schools now. I think Utah has the biggest high school league with over a thousand kids at every weekend race, typically. And I mean, I coached the Utah Leadership Summit for Nica every year and last year I had a kid come up and say, Hey, I was starting high school quarterback and I quit the football team to be on the bike team.\n\nCole Heilborn (28:15): No way.\n\nEric Porter (28:16): Which you would never, ever. That's absurd, right?\n\nCole Heilborn (28:20): Whoa. Yeah. That's surprising. Football. That's the sport. That has been the sport.", "token_estimate": 536, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "25:55", "end_timestamp": "28:20", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "3959860f-634d-481c-8bf8-f92c557242de", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 14, "content": "Eric Porter (28:27): I know. Yeah. So I wonder how that would feel to be the cool kids are the ones that mount bike and snowboard. I mean, at least here in Park City area, those are the cool kids. So who knows? I mean, just an observation more than anything, but I think it gives more people a place to do something and it gives you, the best part to me is that it gives you a lifelong sport because if you are all in with football or any of these other sports, when you're going to get a group of people to go play football in your thirties, it's\n\nCole Heilborn (29:06): Not going to happen.\n\nEric Porter (29:07): No. It's a lifelong thing that you can do when you want, where you want it and keeps you healthy forever.\n\nCole Heilborn (29:14): Yeah. So what would you say to other athletes who are trying to figure out what's next? I'm on the tail end of competing. Where do I go from here? What would you say to them?\n\nEric Porter (29:31): The only way that I've found me is when I follow what I actually want to do. Because when I was getting to where in 2010, where if I did my best run in a slope style, I might qualify. When you're kind of at that point where you're like, okay, I'm not going to win this thing. And if I do the craziest thing I've ever done, I might qualify 15-year-old kids, double back flipping, and I've got a mortgage and a kid. So you're in different life places. So the easy route, that was right when Enduro racing was starting and it was starting to get trendy for that, and I could have chased that and may have been able to do okay, but it wasn't what I wanted to do.\n\nSpeaker 3 (30:20): And", "token_estimate": 406, "speakers": ["Eric Porter", "Cole Heilborn", "Speaker 3"], "start_timestamp": "28:27", "end_timestamp": "30:20", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "6803fd2b-ede2-4dda-9210-3c7c04234c9a", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 15, "content": "Eric Porter (30:21): So I kind of went out on a limb and chased this because all I really wanted to do was go ride my bike in the woods and camp and fish and do that sort of thing. So I figured out a way to do that. And then I've been continuing to do that. So even with YouTube, if I was trying to, my videos are literally just doing what I want to do, which is kind of funny, but it works because it's authentic then and it's real because I mean, there's a million things I could do. I could do how to videos on riding and they crush it. Everybody wants to learn how to manual or whatever. And who knows? I might, I at some point make a video like that if I'm inspired to do that. But I've just felt like I would be jumping in with everybody else that's doing a how to video about whatever it is. And so I had to think about what it is that I want to put out to the world to show people and tell people and bring people into my world. So I think that's the key to it is following, taking that step back and thinking about what is it that I actually want to be doing? And you'll likely be successful with that. You're probably not the only one that feels that way about that segment of the sport or just your life in general. And then just put everything into it. (31:46): You really can't go halfway on it. You got to go all in on whatever you do, and that's the only way to be successful, I think.", "token_estimate": 350, "speakers": ["Eric Porter"], "start_timestamp": "30:21", "end_timestamp": "30:21", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "1dd3baf5-645b-4de3-9adb-46480be33a8c", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 16, "content": "Cole Heilborn (31:55): Yeah. No, well said. Well, we're about out of time for today. It's been super great to chat. We've had a lot of amazing guests on the show. You've definitely been on, I think the different end side of a lot of the guests that we've chatted with. You're, a lot of the people are in the brands asking people like you to be in their films or trying to coordinate the strategy behind whatever they're working on. And I think what's been neat in this half an hour is getting to learn about those experiences from your side. And I think what I've learned is marketing. That's what this podcast is all about, but marketing at its core is just like communication. It's having a relationship and it's telling stories, and that's exactly what you're doing just in a new way that isn't maybe not as conventional.\n\nEric Porter (32:44): Yeah, absolutely. I think that's really, it is being really fluid to see what's happening, where do I need to be? And thinking about things and doing it right when you're ready to do it. And as an athlete, working with the marketing managers who you're talking to, and most of the time in this podcast, one of my big things is how do I make their job easy? And that's a big part of how I'm able to keep a job is what are their goals, what are they trying to do, and how do I make that easy on? So just staying in good communication and sending updates as to what I've done. And yeah, like you said, communication because I'm kind of the megaphone for the company and doing it in a way that is real and isn't saying, go buy this bike, but creating cool experiences around the bike and connecting people, trying to get the emotions and getting them to feel something. And that's how you get that connection with the brand.\n\nCole Heilborn (33:53): Yeah. Well, I think speaking of films, the one you just did with Diamondback, the Grand Canyon trip with your family, if you guys haven't seen that, you should go check it out. It's really well done and it totally hits home at the family feels, so I think that well done. Nice job.", "token_estimate": 519, "speakers": ["Cole Heilborn", "Eric Porter"], "start_timestamp": "31:55", "end_timestamp": "33:53", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "d832fde5-88cd-4fe8-b79a-56a399822904", "episode_id": "9ee7e03d-6aec-4f8b-b0e5-ff1259bad24b", "cms_item_id": "68225dfc7bb476527f8c4844", "chunk_index": 17, "content": "Eric Porter (34:09): Yeah, thank you. And that was actually, that was something that Mike was a part of. You probably aren't surprised by that with the feel, and we all worked together with Jill and with Mike, and then with the photo and video guys to come up with this concept and shoot it and then tell that story. I don't normally have a third party voiceover or script and that sort of thing, so that was really cool to do, for\n\nCole Heilborn (34:39): Sure. Yeah. Awesome. Well, Eric, thank you. Where can people go to follow along if they're interested in seeing what you're up to?\n\nEric Porter (34:46): Yeah, it's Porter, MTB, on YouTube, Instagram, anywhere. That's the easiest way to find me.\n\nCole Heilborn (34:53): Okay. Sounds good. Well, hey, thank you so much and have a good rest of your day.\n\nEric Porter (34:56): Yeah, thanks. You\n\nCole Heilborn (34:57): Too. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learn something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 271, "speakers": ["Eric Porter", "Cole Heilborn"], "start_timestamp": "34:09", "end_timestamp": "34:57", "podcast_index": 31, "episode_name": "Ep 31: Eric Porter | Ride On | Porter MT‪B‬", "slug": "ep-31-eric-porter-ride-on-porter-mtb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-31-eric-porter-ride-on-porter-mtb", "guest_name": "Eric Porter", "guest_title": "YouTuber", "categories": [], "short_description": "\"When you find a sport that you love and you're able to go do it and get out of the real world and go ride a bike. It's the best feeling ever.\"", "podcast_length": "44:53"}, {"id": "6924df7d-a7e0-45a4-9e32-f93d842435ce", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 0, "content": "Cole Heilborn (00:02): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial, and film production company based in the Pacific Northwest. Before we jump into today's episode, I wanted to talk about Darby Communications. There are presenting sponsor for this episode. I've gotten to know them over the last few months as they've helped me with some PR and marketing for this podcast. The Darby com team has designed their process around my needs, combining a people first mindset with an analytical data-driven approach. Today's business world moves fast, but the Darby com team has taken the time to truly get to know me and understand my goals. They've been a great partner to collaborate with, and I'm really impressed with their well-rounded approach that generate real results that actually help bring this podcast to more ears. If you're in the market for a great PR team in the outdoor wellness and fitness industry, go ahead and check 'em out@darbycommunications.com. (01:18): Welcome to the Backcountry Marketing Podcast. Today I'm sitting down with John, hold my the brand manager at UST Camping Gear. John, how are you?\n\nJohn Holdmeier (01:25): I'm doing well. How are you?\n\nCole Heilborn (01:26): Fantastic. Thanks for joining us. Where are you calling in from today?\n\nJohn Holdmeier (01:30): Yeah, so I'm happy to be here. I'm calling in from my house in Columbia, Missouri in the,\n\nCole Heilborn (01:35): Okay, right on. I think that's the first Missouri guest we've had.\n\nJohn Holdmeier (01:39): Man, I like that\n\nCole Heilborn (01:41): You're representing the whole state.\n\nJohn Holdmeier (01:43): Yeah, that's a lot of pressure. I don't know.\n\nCole Heilborn (01:47): No, no worries. So tell us a little bit about UST. Who are you?", "token_estimate": 550, "speakers": ["Cole Heilborn", "John Holdmeier"], "start_timestamp": "00:02", "end_timestamp": "01:47", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "695c7fd3-543c-4b87-8629-fcf6536b2c99", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 1, "content": "John Holdmeier (01:52): Yeah, yeah, I'd be happy to. So I think the place to start would probably be with some of the history of where the brand came from. It's been around for a long time. So UST started in 1936, which surprises people long, long time ago. They started in the maritime safety and rescue side of things. So the first item that UST made was actually a rope cannon that shot a rescue rope from one ship to a sinking ship. So that's where the brand began and where it got its start since the thirties. So it was based up in New England around that time. And then since the thirties, it shifted a little bit more towards survival towards rescue and survival, not just maritime, but just general rescue and survival. And the brand shifted down to Jacksonville, Florida, which is where its previous location was.\n\nCole Heilborn (02:51): Okay.\n\nJohn Holdmeier (02:53): And then from Jacksonville, things started going more towards from just the survival into the camp accessory, everyday camping items. So they started getting into, I would say mid two thousands. They really started getting into camp stoves, camp cooks, some of the everyday items. So kind of branching out from that survival background. And then I think the most recent thing chapter to bring us up to date is that the brand was acquired by our parent company A OB, and moved up to Columbia, Missouri. So that moved, just happened within this past year that we moved up to Columbia, Missouri, and that's when I came on board as the brand manager. So I've been around for a year, a little over a year now as brand manager.\n\nCole Heilborn (03:45): Okay.\n\nJohn Holdmeier (03:46): Yeah. And so that's kind of the not so short version of it.\n\nCole Heilborn (03:51): That's great. It sounds like, I mean, you guys have been around for a long time, but recently you've had a lot of changes. What has the acquisition and the changes that have come out of that looked like?", "token_estimate": 486, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "01:52", "end_timestamp": "03:51", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "226c861e-62bd-471b-ab60-b4d662080311", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 2, "content": "John Holdmeier (04:03): Yeah, so it's been really exciting for us because most of the people in the Columbia location, since we've moved up to Columbia, we have a lot of new people involved with the brand, myself included. And a lot of our core marketing group is included in being new to UST. We wanted to, as that shift kind of happened physically from Jacksonville up to Columbia, we really wanted to take a look at everything that, all the products that the brand was making, the marketing the whole thing through and through. We wanted to take a look at everything and really try to be intentional about the things that were working well before and the things that weren't working well and try to bring the things that were working well along with us as we updated for the future. The big directional change for us as a brand is we just launched our first line of products out of our Columbia location with a new brand direction. So we've done a complete brand refresh, new logo, new look, new colors, and along with that, the products that we've gotten into have been the core camping items. We started this first line was sleeping bags, tents, sleeping pads. We really wanted to branch beyond or grow beyond the camp accessory space. And that's kind of where we're headed for the future, and we're really excited about it.\n\nCole Heilborn (05:33): Yeah, that's great. So with this headquarter move, this acquisition change, you guys felt like it was a good time just to kind of do a whole refresh and a whole reset. I guess. Where did that motivation to want to do the reset come from?", "token_estimate": 398, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "04:03", "end_timestamp": "05:33", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "45dad6e8-0ebb-4c0c-afdb-73824446ef40", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 3, "content": "John Holdmeier (05:50): It was just kind of the whole team, honestly, looking at what the brand was currently and honest about that. And the brand had a lot of good things going for it up until the move, really good distribution. So in a lot of the key retailers, your reis, Dick's Sporting Goods Academy, you name it, we had really good placement. The brand itself didn't have outstanding brand identity, brand awareness, I wouldn't say so. While a lot of people used UST products and had them in their camp supplies in the camp box, they wouldn't have known UST from a lot of other brands. So as we looked at it, we realized that this kind of the old look, the old color, the old feel, the old products kind of blended in with the rest of the market myself. I mean, I knew of UST coming onto the team, but once I started to really look at it and I was thinking about making this move, I went through my own camping gear and realized that I had like seven UST items that I didn't know I had, that they were UST items in my gear. So that is kind of the reasoning behind us, realizing that we needed to refresh it, give it some new life, and make an exciting new direction for it.\n\nCole Heilborn (07:11): Yeah, man, that's got to be a lot of one fun, but also challenging. You guys have been around for a long time. You have a ton of history. People obviously use your equipment, so you make good product, but not many people could actually pick you out from a lineup. How have you guys worked through that? I guess let's kind of take a dive into the last year in this brand refresh.", "token_estimate": 396, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "05:50", "end_timestamp": "07:11", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "731d4cfb-c47c-4023-8569-ff76656373e1", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 4, "content": "John Holdmeier (07:39): Yeah, yeah. I think probably the best place to start would be where we started. When I came on board, it was me and we had a few other new people specifically like our graphic designer, Haley, and a few other key team members that just started around the same time. We sat down and looked at everything. We looked at industry trend information, but then we also looked at our brand and other brands that maybe we admire a little bit of the whole all encompassing look at all of it and how it fit together. Our first step to that was to gather as much information as we could about the industry, about the consumer, about the market, about all of it, about gear trend, about everything, and then try to decipher all that information. The best way that we found to do it, and the most important thing in the process I would say, was we came up with these consumer personas, (08:40): And what they really allowed us to do was hone in on who we were making this product for. And I try to stay away from overgeneralizing groups of people or demographic information. I don't think things are that cut and dry and easy to look at and categorize people. So we wanted to steer clear or be mindful of that while we were doing this consumer persona exercise. But we took a lot of time to do it really well. And you'll see a lot of brands that will do a consumer persona exercise. They'll come away with one or two consumer personas. And so we actually came away with seven from ours. We wanted to be as all encompassing as we could be and appeal to as many people as we could appeal to. And what we did for each one is we actually thought of these storytelling avenues that we wanted to approach. And so those look like the canoe kayak camper would be one of our avenues. The rock climbing camper would be another one of our avenues. The family camper would be another one of our avenues. So we came up with seven avenues like that and then built these consumer profiles to fit those avenues. We have, I think it's like 35 points of information about each one of our consumer personas. (10:09): We went really deep with 'em. I think at first Haley was kind of like, wait, why are we thinking all this stuff? And we sat there and figured out what kind of car would this person drive? What kind of music would they listen to? Who are they friends with? What are their favorite clothing brands? You name it? Just a lot of that type of detailed information. And what that allowed and what it came through for us with is that as we showed these to people within the brand, and as we show 'em to people outside of the brand, people are going, oh man, I know that person. These are real people. They we're like, no, we actually, we just kind of thought of all of these details to fit these avenues of storytelling that we want to pursue. And the other thing we kept in mind through this process is we wanted to keep these as inclusive as possible. So we wanted it to be a really diverse and well-rounded group of people that we're keeping in mind as we do everything.", "token_estimate": 769, "speakers": ["John Holdmeier"], "start_timestamp": "07:39", "end_timestamp": "07:39", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "53aed925-b6d3-4072-91ca-cf1f06119a4a", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 5, "content": "Cole Heilborn (11:19): Wow. I love that detail. What has that allowed you to do as you've moved forwards from there?\n\nJohn Holdmeier (11:26): Yeah, so honestly, the consumer personas, I would say are probably the most important thing. They were the most important step in everything, and it was the first step that we did because we couldn't come up with our color or our new color palette or our new logo or our new look or any of our brand personalities until we knew that information. (11:49): So what that has done for us in that level of detail, what that's done for us is it serves as our ultimate check. As we do anything for the brand, we take it back to those consumer personas and we say, does this fit? Who out of our people are we trying to speak to with this product or with this story that we want to tell? It really allows us to stay true to our core brand identity. And none of that would've been able to be formed without the information that those personas provided for us. So I would say it's been probably the most integral thing to the entire processes is those personas, and then how we use that and how we make sure that we stay on top of checking everything against that.\n\nCole Heilborn (12:34): Sure. Sure. So you're, I know another thing that you guys have gone through and refreshed, and I think you even have your own podcast episode about it. It's defining your values. Did you set your values and then develop your character personas, or did you find your consumers first and then develop your values,", "token_estimate": 383, "speakers": ["Cole Heilborn", "John Holdmeier"], "start_timestamp": "11:19", "end_timestamp": "12:34", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "ea4c01f2-19ca-4c10-91cd-7becd5a12528", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 6, "content": "John Holdmeier (12:53): The values and the persona? That's a good question. Actually, I can't remember the order that we did those two things in. I want to say that we started the consumer persona exercise and the values around the same time, and they feed each other, honestly. I mean, it's us figuring out what's important to the people who want to use our products and making sure that we are in line with those things that are important to those people, not because that's what makes us successful and be able to sell things, but ultimately that's what our people will resonate with and what'll create the atmosphere and the family and all of the things that we want our brand to have. So in order to speak to the people that we want to speak to, we have to be about the things that we want to be about. So they're kind of simultaneous, I would say.\n\nCole Heilborn (13:43): Yeah, that makes sense. Like you said, they feed each other, they're built on each other. Yeah. Interesting. Okay, so I think one of the things that I've really enjoyed about you guys and getting to know you and understanding more about the team and what you guys are working on is that you are entering the camping outdoor world, which is very saturated. There's tons of stuff out there. There's plenty of options if you want to go find a backpack or a sleeping bag, but you guys are doing things differently, and as your podcast name suggests, it's called the shakedown. And I feel like that lends itself to what you guys are doing well in pretty much every regard in your business. For those people who aren't familiar with you, what are you doing differently? How are you trying to break into this already crowded space and stand out?", "token_estimate": 429, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "12:53", "end_timestamp": "13:43", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "cb9d633c-7310-4ca4-b491-1c65888aae93", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 7, "content": "John Holdmeier (14:36): Yeah, yeah. I appreciate that you get the play on the podcast name and what we're doing with the brand. It is, it's just like a shakedown. It's looking at the things that we're working and what's going to work, and then ditching the stuff that's extra that we didn't need. Yeah, that's intentional and I appreciate that. (14:56): Yeah, I would say that the thing that makes us different, that really sets us apart from it is a crowded market. I think to that point though, I would say that it's growing, so there's a lot of room. So that's exciting. And I think there are a lot of big shifts happening within some of the older brands that have taken up a lot of the market space previously, not necessarily adjusting their strategies and allowing for new players to come in. We're not necessarily a new player in the space, but I feel like the way we're approaching things is kind of that same startup mentality and that same small, we have a pretty small team, so that's kind of how we're approaching it as this startup mentality. There's a lot of space there for us to grow into, I feel like as the market grows. So the thing that sets us apart from the rest of the market, I would say it's a list of things. Number one is we do more of a range of product than any other brands in the space. So there aren't other brands that will make all the camp accessory items and then also make camping tents\n\nSpeaker 3 (16:07): And", "token_estimate": 362, "speakers": ["John Holdmeier", "Speaker 3"], "start_timestamp": "14:36", "end_timestamp": "16:07", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "8d2cc66b-8078-4cc7-a0fc-326f89a3b70c", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 8, "content": "John Holdmeier (16:07): Also make sleeping bags and air mats, and also have survival equipment and the fire starters and all of that. So there are brands that do really well with the accessories, and there are brands that do really well with the bigger ticket items, and there's not a whole lot of our competition that runs the whole range. So we have a pretty all encompassing approach to camping in the outdoors, which I think sets us apart. The other thing that sets us apart, and it's not to say that there's nobody else out there who is innovative, there are obviously other innovative brands out there, but we're making that a requirement for every new product that we come out with is that it has to have something that's better than what we're seeing, and that's innovative. We want to have some sort of uniqueness to each one of our products. It's been interesting. I've been in the industry for a little while now, and watching a lot of the factories from overseas be able to start their own brands and sell online and sell through Alibaba and Amazon and all of those things and how they work with brands that are just starting up in the us, it's pretty easy to get copycat type of equipment. (17:19): And so the reason that we approach design the way we do and that we want to make really high quality gear that's innovative is we want our stuff to be different than any of that menu from the factory kind of approach that a lot of brands do take, and it works for a certain customer, and they see some short term success, I think, with those things, but we're trying to build this thing for the long haul. So I think that's another thing that makes us different.\n\nCole Heilborn (17:50): Yeah, no, that's great. And speaking of innovative products, I was looking at your website earlier, and I don't remember what it's called, but you have a sleeping bag that has these wings that fold in and you can adjust the temperature rating of the sleeping bag, and you have three different rating levels depending on essentially how many layers you add to your sleeping bag. I've never seen that before. That's cool.", "token_estimate": 530, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "16:07", "end_timestamp": "17:50", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "222c81e7-640e-45cb-9e26-7db60889d2d1", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 9, "content": "John Holdmeier (18:15): Yeah, thank you. We're really excited about that one. It's called the Monarch. The Monarch, that's right. Yeah. And it's of the wings, the play it with the Monarch butterfly there, the fact that it has wings, essentially. It was myself and our head designer Anton. We started looking at sleep systems and how my experience previously, my past experience, I worked a lot of retail. I worked at a small shop in the Midwest in St. Louis called the Alpine Shop. And so I spent a lot of time on the retail floor and just the memory and the recollection of everybody coming in needing at least two sleeping bags, it's like I got to have one for winter and one for summer, or whatever it is. Or they're buying a sleeping bag for their kid to go on a scout trip or whatever it is, and people having to continually buy more than one product to fit that need. So we wanted to build something that had versatility that could be kind of the last sleeping bag you need to buy because it's adjustable. And so that was our mission as we approached kind of what our take on sleeping bags would look like, and that's where that came from.\n\nCole Heilborn (19:29): Okay. No, that's great. That's cool to hear the backstory because yeah, you're totally right. I mean, I am thinking about my own gear closet and my wife has two sleeping bags and so do I because you need one for warm and one for gold. Very cool. So coming back to your customer personas and understanding who your audience is, I think I'm curious to dive into that, understand, and then look at your guys' design, your colors, how you've chosen the tone of your brand, and what audience are you, let me rephrase that. Who are you talking to with your design? What customer profiles are those?", "token_estimate": 441, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "18:15", "end_timestamp": "19:29", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "fcf630dd-2a55-4513-9607-64876b0ce6aa", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 10, "content": "John Holdmeier (20:19): Yeah, yeah, for sure. So to get a little further into the consumer persona, the profile and then how that shaped our brand identity. I'd say the way we approach how we want to look and sound and feel as a brand is it's specific to those people. And so we want to be able to do things like be enthusiastic, be self-aware as a brand, we want to sound a little more casual than a lot of the traditional legacy brands will sound. We want to try to be funny and a little bit irreverent where we can, A lot of those things are directly from looking at our consumer personas and what we built out there and what we think those people are looking to hear from a brand and what they would identify with. So everything from the bright colors and the new color palette to how we look and sound and feel. (21:11): It's all driven by looking at our people and what kind of music they listen to, what kind of vehicles they drive, all that detail that we put into those consumer personas. We're trying to figure out what we think will resonate with those people, because that ultimately is the core of who we are as a brand. And the cool thing about it is that it's a direct fit to who we are as a team at UST. All of these things that the brand sounds like and looks like and speaks are pretty representative of our team in the marketing department specifically and across the board. But we decided early on that we wanted to be able to speak to the taste of music that our brand likes, or we filled out all the same information for our brand that we did for the consumer personas, and we came away with, we really like folk in Americana as a brand, but also we're into nineties hip hop because our main designer, Anton, myself, our creative director, we're all kind of hip hop heads. And so it's a direct reflection of who we are and how we think that that would resonate with the personas that we develop. So everything from the colors to the look and the feel and the sound.", "token_estimate": 497, "speakers": ["John Holdmeier"], "start_timestamp": "20:19", "end_timestamp": "20:19", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "4a14a94d-2648-4a99-ab6e-1080a9fe2d94", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 11, "content": "Cole Heilborn (22:28): And one of the things that I noticed and I appreciated is that I feel like I'd be curious to see your customer profiles because I think this supports who your personas are, but everything about your brand is inviting. It's friendly. It could either be the weekend warrior or it could be the two week road tripper. And I don't feel like there's a lot of, and I think you spoke about this, there's a lot of legacy brands out there who are pretty hardcore, they're elite athletes, and that reflects in their product design, in their media, in their marketing, in their copy. And you guys are taking a totally different approach where you're a little more opening, you're inviting, you have a sleeping bag called the Monarch, and it's playful and it's fun. And I feel like that's got to resonate so well with people who are just getting into camping or are trying to figure it out or are maybe a little intimidated by the industry and are unsure where to start.", "token_estimate": 245, "speakers": ["Cole Heilborn"], "start_timestamp": "22:28", "end_timestamp": "22:28", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "60cab45c-043d-4b3a-825e-0dd9c5283bb9", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 12, "content": "John Holdmeier (23:34): Yeah. Yeah, I appreciate that thought because that's exactly what we're looking for and what we want to be for our customers. I think you're right, A lot of people, they aim for that Apex athlete, really intense, epic kind of outdoor consumer, and I'll promise day after day that our products are going to be able to service that person. They're really high quality products, so we do want to keep that in mind as we design our products that they can be used in that way. However, we just wanted to approach things to make them more accessible and approachable. And those words that you use like approachability, accessibility, inclusion, all those things are baked into our core values and what we came up with for our core values. So from the colors to the product to the product names, we want it to be fun and approachable because that's the majority of people who are camping. (24:35): And there are a lot of people every year who get into this realm of the outdoors as new campers, and we want to feel like we're welcoming them in and not making it seem like it's an intimidating experience. I would say that that comes from, a lot of that honestly, comes from not just myself, but I have a lot of experience on the retail side of things of customers coming into the store and being afraid to ask a question because they don't want to sound dumb, or they don't want to come across as admitting that they don't know what they're looking for or that they don't know what they're talking about. So that's kind of an entry, a barrier to entry in our industry that as we were looking at how we wanted to make this thing, I thought we want to make this as approachable as possible. So it's definitely why we did it that way.\n\nCole Heilborn (25:27): That's great. Yeah, I mean, I think that's a great way to approach it. Lots of people who are trying to get into it who don't have experience or don't have the, I dunno, a parent or a grandparent who's done it and can pass along that knowledge. But if you guys can be there to invite everyone and be like, Hey, come hang out with us. We'll show you how to get started. That's super rad.", "token_estimate": 540, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "23:34", "end_timestamp": "25:27", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "c719ae1f-1f02-4cc7-83e6-c1025fbc2d48", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 13, "content": "John Holdmeier (25:52): Yeah. Yeah, that's exactly it. We want people to want to come hang out. That's kind of all we're looking for. We just want friends.\n\nCole Heilborn (25:59): Yeah. What's been the hardest part of this brand transition over the last year?\n\nJohn Holdmeier (26:06): I would say the biggest challenge of this whole year in this whole brand refresh process has been the scale of everything. It's a lot of hours, it's a lot of hard work, a lot of people involved, and our brand had a lot of products out there, and so just the size of our SKU count and the size of everything has been a lot to deal with. So I would say that's our biggest challenge. It's surprisingly large brand that you might not have of before, and so to turn a ship around that's a pretty big ship has been a lot of work. So I would say that's probably been the biggest challenge.\n\nCole Heilborn (26:53): And how have you tackled that? How have you managed to wrap your head around that challenge?\n\nJohn Holdmeier (27:00): Show up every morning? I would say we just keep plugging away at the little things. We do what we can do every day, and we try to keep the big picture in mind as we look at things, because whenever you are getting kind of bogged down in the details of some of the be it packaging updates or whatever small detail you want to talk about, the day to day of that can be pretty overwhelming. So we try to do a good job of stepping back and kind of keeping the big picture and the big goal in mind and just reminding ourselves of why we're doing what we're doing.\n\nCole Heilborn (27:39): Yeah. That's great. I'm curious, how did you keep, a year ago you were like, okay, we got to go down this path. We have all these things to do. How did you know what to do and in what order to do them? And how did you keep the ship on track as you're working towards this everything?", "token_estimate": 469, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "25:52", "end_timestamp": "27:39", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "a75a52ff-9773-48fa-85bb-c9d2ba8b2264", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 14, "content": "John Holdmeier (27:58): I think that's a really good question. I think that the way we approached it was it's a real team effort in that everybody's saying, well, we have to think about this thing. We have to think about this thing. And sitting down at the very beginning, I would say the best thing we did upfront was really take some time about a little over a year ago to sit down and spend the time upfront on all of this. Before we started scrambling, trying to make progress, we sat down and we took the time that we needed to take to plan it out. (28:37): Personally, I don't have a scholastic background in marketing or brand or anything like that. I just grew up in the industry and have been following brands my whole life. So that's kind of where my knowledge comes from, is just watching what other brands have done. As I grew up and as I worked in the industry, I listened to a lot of podcasts, a ton of podcasts, read a lot of marketing books, brand books. I think that it's really easy for people to get down on marketing or those sorts of things, thinking that it's trying to, it's only about selling product to people, and it's only about, there are a lot of negative things that people feel like, I feel like I've been pretty lucky in my approach to it in the way that I've come to it, through just seeing brands that I admire. I have a lot of good examples of how to do it and how to do it the right way. That's not salesy, that's not gimmicky, that's not all of those things. And so it was really cool for us to be able to sit down upfront and kind of take the time to say, these are the things we know we don't want to be, and these are the things that we do want to try to be and plan it all out that way.\n\nCole Heilborn (29:48): Yeah. Was that intimidating for yourself?", "token_estimate": 449, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "27:58", "end_timestamp": "29:48", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "252457d8-69b6-4b1c-9b2a-6be4a7d9d159", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 15, "content": "John Holdmeier (29:52): It was exciting more than anything, honestly, looking back at it, maybe I should have been a little more intimidated than I was at the beginning of it. It was a pretty lofty goal to set out on, and at the time I had no idea how much work or the size of all of the work or any of that. So I probably should have been a little intimidated, but I feel like I was more excited to go on this journey with the team that we have. So I would say no, it honestly wasn't really intimidating upfront.\n\nCole Heilborn (30:27): Yeah. Well, that's a good way to, what do they say? Sometimes being a little naive is helpful. Yeah,\n\nJohn Holdmeier (30:32): Yeah. Yeah. Ignorance or ignorance being bliss,\n\nCole Heilborn (30:35): However. So what's next on the horizon for the brand? What are you guys working on today and what's tomorrow look like?", "token_estimate": 214, "speakers": ["John Holdmeier", "Cole Heilborn"], "start_timestamp": "29:52", "end_timestamp": "30:35", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "3ddb12a9-0932-4406-9546-819a1186257e", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 16, "content": "John Holdmeier (30:46): Yeah, I think there's a lot on the horizon for us. It's hard to pick the most exciting, I would say with COVID and the way things have been going. That slowed down our ability to do a lot of the storytelling that we wanted to do upfront. And so our brand launch and our new product launch have not really had all the cool storytelling and imagery and stuff that we wanted to go along with them just because of the way things have been. I think as we go forward and hopefully as things begin to be a little bit more normal, who knows what's going to happen next week or next month, but I really look forward to a lot of the stories that we're going to be able to tell. We're starting to get creative with how we can still do that kind of stuff and be safe. (31:38): And so storytelling is at the core of what we hold to our heart as a brand. It's one of our values. Beautiful and creative storytelling. I'm really excited to round out a lot of that side of the brand just because we haven't really been able to, we've gotten some cool stuff done, but we have a lot of really fun stories that we're lining up to tell. And then I would say we're going to continue to round out these camp items that we've gotten into. And so I'm really excited about the new products that are going to be coming out on the next round. And I'm really excited to see how this line of products is received, because it just launched last month. Our website's only been up for about two months now. So I'm excited to see a lot of those things in the future. We always say internally, we look forward to the future, but we also don't want to have too much expectation. We want to just take it as it comes and be present. Yeah.", "token_estimate": 431, "speakers": ["John Holdmeier"], "start_timestamp": "30:46", "end_timestamp": "30:46", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "23527eb8-ef83-4db3-83b7-def8c6a6e075", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 17, "content": "Cole Heilborn (32:36): Well, I think that's great, and there's so many companies out there, and I'll make a generalization that don't, I think go through the steps that you guys have gone through when trying to understand who you are, who your customers are, defining your values, and I think that's great that you guys have taken the time to do that. And I think it sounds like you've done it right, rather than just trying to rush it and get product out there and slap a new logo on it. Yeah.\n\nJohn Holdmeier (33:06): I think people can tell nowadays it's important that brands believe in the things that are important to the brand and important to the consumer. And I think that people are wanting gear that lasts a long time from a brand that they believe in. And so that's kind of driven what we're trying to do. I think slapping a logo on something can only get you so far, so\n\nCole Heilborn (33:33): That's right. Well said. Well, John, we're just about out of time for today, but if people would like to follow along with you personally, the brand, where can they go?\n\nJohn Holdmeier (33:44): Yeah, yeah, for sure. So my Instagram is my name John Hold Meyer. It's just all one word, no spaces. It's H-O-L-D-M-E-I-E-R, and then the brand UST on Instagram. Our website, it's UST gear, both places. So all one word, nothing in there. Just ust gear.com or at UST gear, so\n\nCole Heilborn (34:09): Facebook\n\nJohn Holdmeier (34:09): The same. Yeah.\n\nCole Heilborn (34:10): Okay. And the podcast too, that's on Apple and Spotify. I'm hoping it comes back soon.\n\nJohn Holdmeier (34:17): Yeah, yeah. We'll be back at it being remote and all that kind of, we're new to the podcast game, so that kind of threw a wrench in some of our plan. We were just getting on a roll with our third episode and then we kind of had to pause things, but we actually were talking today, we had a little conversation about how we're going to get it back up and running. So yeah, check out the podcast as well. The shakedown, if you go to ust gear.com, we have our blog, the podcast, all that stuff is linked up on the website as well.", "token_estimate": 529, "speakers": ["Cole Heilborn", "John Holdmeier"], "start_timestamp": "32:36", "end_timestamp": "34:17", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "b4943f72-b5a3-4507-89ea-d12d292a49fc", "episode_id": "1af9b6a9-c117-45f3-9ac5-eacb91a911b7", "cms_item_id": "68225dfc7bb476527f8c4841", "chunk_index": 18, "content": "Cole Heilborn (34:45): Okay, great. Well, John, thank you so much. I'm excited to see what's next for you guys. We will be cheering you on over here from the west coast.\n\nJohn Holdmeier (34:53): Yeah, we really appreciate it. Thanks a lot for having me on.\n\nCole Heilborn (34:55): Yeah, take care.\n\nJohn Holdmeier (34:56): Yeah, you too.\n\nCole Heilborn (34:57): Alright, bye. You too. Thanks again for listening to this episode. If you enjoyed it, please consider sharing it with a friend or leaving us a review on Apple. Also, remember to check out Darby Communications. If you're looking for a great PR and marketing team, go ahead and find 'em at darby communications.com.", "token_estimate": 169, "speakers": ["Cole Heilborn", "John Holdmeier"], "start_timestamp": "34:45", "end_timestamp": "34:57", "podcast_index": 32, "episode_name": "Ep 32: John Holdmeier | The Shakedown | UST Gea‪r‬", "slug": "ep-32-john-holdmeier-the-shakedown-ust-gear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-32-john-holdmeier-the-shakedown-ust-gear", "guest_name": "John Holdmeier", "guest_title": "Brand Manager, UST", "categories": [], "short_description": "\"We wanted to approach our product line in a way that is extremely accessible to every outdoor consumer.\"", "podcast_length": "44:54"}, {"id": "c5713653-d6cb-4764-9f4b-806f0c82d801", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 0, "content": "Cole Heilborn (00:02): Welcome to the Backcountry Marketing Podcast. My name is Cole Hilborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Before we jump into today's episode, I wanted to talk about Darby Communications there. They're our presenting sponsor for this episode. I've gotten to know them over the last few months as they've helped me with some PR and marketing for this podcast. The Darby com team has designed their process around my needs, combining a people first mindset with an analytical data-driven approach. Today's business world moves fast, but the Darby com team has taken the time to truly get to know me and understand my goals. They've been a great partner to collaborate with, and I'm really impressed with their well-rounded approach that generate real results that actually help bring this podcast to more ears. If you're in the market for a great PR team in the outdoor wellness and fitness industry, go ahead and check 'em out@darbycommunications.com. (01:18): Welcome to this episode of the Backcountry Marketing Podcast. Today I'm sitting down with Andrew Gibbs Dabney, the founder at Lives and Design. Andrew, how are you?\n\nAndrew Gibbs-Dabney (01:26): I'm doing really good today. How are you?\n\nCole Heilborn (01:28): Doing great. Yeah, thanks for joining us. Where are you calling in from?\n\nAndrew Gibbs-Dabney (01:31): I'm here in Fayetteville, Arkansas. I'm nestled in the Ozark Mountains.\n\nCole Heilborn (01:36): Okay, beautiful. It sounds like you've been staying busy with not work, certainly, but also a little mountain biking lately.", "token_estimate": 507, "speakers": ["Cole Heilborn", "Andrew Gibbs-Dabney"], "start_timestamp": "00:02", "end_timestamp": "01:36", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "b49a54f9-dfab-4700-bce0-1242287aec8d", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 1, "content": "Andrew Gibbs-Dabney (01:44): Yeah, that's pretty much my favorite thing to do. My number one outdoor sport, and I'm lucky to have grown up here, but also watched northwest Arkansas turn into somewhat of a mountain biking hub or mecca, or if you listen to the local organizations, they call it the mountain bike capital of the world. But yeah, either way, it's great. We have just incredible trails. It's one of those places where if you don't visit a system in about three weeks to a month, you see a new trailhead sign next time you go. So it's just kind of spoiled for choice here. So\n\nCole Heilborn (02:18): That's funny because I feel like every mountain bike hub across the country considers themselves the capital or the mecca or the hub.\n\nAndrew Gibbs-Dabney (02:29): Yeah. I'm not going to speak to the legitimacy of the claim, but I will say that it's a pretty unique, I've mountain biked all over the country, and it's a unique spot, like I said, just from access, the amount of trails, the amount of development that's happening on just a, I mean a daily basis. I don't remember, I'm someone's going to fact check this, but I think it's somewhere, it's over a mile a week of new single track, and it may be more like three or four miles a week\n\nSpeaker 3 (02:55): Being\n\nAndrew Gibbs-Dabney (02:55): Built of professional built trail here. And it's cool. It's rock features, metal features, stone features, big berms, big jumps, and then also some good natural tech. So that was what was here before. So they're kind of adding on top of that natural kind of flowy, southeast, Mid-South, Midwest, whatever you want to call us, that classic tech\n\nCole Heilborn (03:17): Man. That's awesome. How many miles are there total?", "token_estimate": 433, "speakers": ["Andrew Gibbs-Dabney", "Cole Heilborn", "Speaker 3"], "start_timestamp": "01:44", "end_timestamp": "03:17", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "89b7db81-1497-4479-a4b8-3d3c8a4e7560", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 2, "content": "Andrew Gibbs-Dabney (03:20): I think there's about 450 miles a single track right here around the city centers. And then another cool thing about it is that it's all linked by, I think it's, I forget how much, but there's a paved multi-use trail system that connects all four of the major towns and cities in this region. So you can actually ride from Fayetteville where I am, up to Bentonville, which is about 30 miles up without hitting a public road on bike pass. And then there's splinter and spur trails that go off each way so you can actually access all the dirt by riding on a paved trail system that's specifically built for biking. So it's pretty nice actually. I like it.\n\nCole Heilborn (03:57): That's cool. Well, I'll have to come down there and check some of those trails out. That sounds pretty incredible. But tell us a little bit about Lipson. Who are you?", "token_estimate": 219, "speakers": ["Andrew Gibbs-Dabney", "Cole Heilborn"], "start_timestamp": "03:20", "end_timestamp": "03:57", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "1beb5c66-99d1-48b3-9fcb-5a99c291004a", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 3, "content": "Andrew Gibbs-Dabney (04:05): Yeah, we're fairly new. If you've heard of Lipson, you've probably seen our Flex Canvas pants that are getting some attention lately. We're on the outside buyer's guide and year junkie called us their favorite pants of 2020, which was really cool. But really the brand was born out of a long-term effort that I had to simplify the things that I own, pair down the gear, pair down, especially the clothing that was in my closet and get to a few of my favorite things as opposed to just so many options, so many shirts, so many pants, all that kind of stuff. And so really what we're born out of is owning less stuff, but better stuff. And that's what fuels our part development, the design philosophy, everything down to the way we do our operations is don't clutter it with just so many options and so many things that we really can't manage. (04:53): We're going to make a few things and we're going to make 'em as high quality as we possibly can and then iterate fast to make 'em even better as fast as we can as well. That's what we have as our advantage as a new company is the ability to get out of the market, test it, listen to people and make it better. So that's lives in less stuff, better stuff, and it's working so far. People really like the pants. I like them. I made 'em as the pants. Were kind of a side project actually in our initial development because it's a product that I didn't have I couldn't find, which is a real tough pair of all round outdoor pants that fit someone built like me, which is fairly slim and athletic and didn't want that big boxy pair of pants and try to put a lot of features without calling attention to it. And it seems like we've struck on a little bit of something that works\n\nCole Heilborn (05:44): And it's cool, kind learn your backstory. And I enjoyed our conversation earlier, and you guys have only been around for a couple of years, right?", "token_estimate": 481, "speakers": ["Andrew Gibbs-Dabney", "Cole Heilborn"], "start_timestamp": "04:05", "end_timestamp": "05:44", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "544e70ab-3ddc-4424-b68d-094d842d18fc", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 4, "content": "Andrew Gibbs-Dabney (05:51): We started officially in 2018 beginning, and then we launched our first Kickstarter campaign in September of that year. And then we've done another Kickstarter the next year, and then we've kind of gone on to direct sales, but pretty in the market for about two years.\n\nCole Heilborn (06:10): Okay. And how many products do you have? Do you offer?\n\nAndrew Gibbs-Dabney (06:15): Currently we have two available. We have the flex canvas pants and the high wool fleece, and the high Wolf fleece is great. It's a polar tech high LT body with a polar tech power wool panel. So in layman's terms, what that means is very breathable and if you put a shell over it, it's very warm. And the wool panels while being stretchy and warm are also anti odor. What's funny is though, and why we focus so much on pants now is that we've been outselling pants to fleeces three to one. Even when we were sold out of pants, people have been the world kind of said, Hey, I'm not sure we need another black fleece, but you're onto something with these pants. And so coming up, we're actually launching a new pair of pants called the Ecot Trail Pants, and they're built on what we've learned from the Flex canvas, but they have zero cotton content. (07:05): They're a nylon spandex blend, and the nylons actually source from recycled ocean buoys. So it's really cool, it's really sustainable. But they've also, from a performance standpoint, they're great. They've got a good drape, they've got a good feel, they wear well, but they also stretch, they wick sweat incredibly. They're DWR, they're coated with a water resistant treatment and like I said, building on the same fit and a lot of the same features as the flex canvas pants, but something without cotton. So a lot of our customers want to take one pair of pants, and if you're going to go out for many, many days and you don't know what the weather is, you prefer to have something that's a full synthetic. So (07:46): That's coming out in October. And then we're actually offering a women's version of the Flex Canvas pants, a fully featured women's version with deep pockets and everything that the men's version has, which is something that's been important to us, is not to just offer not as good product for the women's version. And then we're doing shorts to follow up with that next season. So really below the waist and building on what we know, which as a small brand is really all we can do, and we don't want to overextend and overpromise and we feel like we can really do well in this category.", "token_estimate": 643, "speakers": ["Andrew Gibbs-Dabney", "Cole Heilborn"], "start_timestamp": "05:51", "end_timestamp": "06:15", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "8c5637b6-e145-4d14-9916-952f174a6ff9", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 5, "content": "Cole Heilborn (08:20): And I think that's neat. And it's maybe unique to launch a brand I feel like with only one or two products, but you've said those one or two products, you guys focus everything out on those and you make 'em darn good. And some brands might suggest, well, we should diversify and get a whole bunch of products out there where you guys are like, no, we're just going to niche down, make something super solid and just focus it on that and then iterate as needed.", "token_estimate": 121, "speakers": ["Cole Heilborn"], "start_timestamp": "08:20", "end_timestamp": "08:20", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "60d892d7-9c12-4bd2-9b3c-c6a09928e8db", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 6, "content": "Andrew Gibbs-Dabney (08:50): Right. I mean, it's a big part of, like I said, there's a lot of philosophy that's gone into this brand from the start. Before I ever started designing products, I wrote down our company values and our production principles and how we design products and how we go about this process. And it's really a quality over quantity approach. And when we have a small product assortment of something that we've really designed, that we've really tested that we really feel confident in, then we can really market it. We can really talk about its benefits, pros and its cons. If someone wants to ask, Hey, is this the right pan for me? We really know how to answer that question. And from a QC design financing everything, it's just easier when you have lower product count. We can really control that process. We can fund it easier. We can take less inventory risk putting in all of our eggs in one basket. (09:44): And some people are listening saying, there's an obvious con to this. There's a lot of risks because if that doesn't work, which is true, but I think there's more risk in putting out 12 products for your first collection of 10, of which there's no way you can really guarantee that they were developed well, they were prototyped to the fullest extent and they were qcd as they came off the line. If you're a new company, I mean, hell even, it's hard enough if you're a big legacy company, some of these brands have thousands of SKUs in each collection and they cycle every season. You can't guarantee quality at that level, no matter how many employees you have on your team. So like I said, it goes back to the DNA of what we do and how we think about it. It goes beyond just the kind of marketing and it goes into how we actually operate, and that's part of it.\n\nCole Heilborn (10:29): Yeah, no, I love that. That goes down the whole topic of sustainability within the industry, which I know you're something you're really passionate about when it comes to marketing. How have you guys decided to position yourself, talk about what you do, what's your approach?", "token_estimate": 525, "speakers": ["Andrew Gibbs-Dabney", "Cole Heilborn"], "start_timestamp": "08:50", "end_timestamp": "10:29", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "0702f138-d296-40e9-ab73-a2eadf634271", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 7, "content": "Andrew Gibbs-Dabney (10:49): Yeah, it's hard. So I'm a wordy person, especially when I write, and I want to get the value proposition for what we do outright. I want to tell the whole story. I want to start with the genesis and the thought behind it, then get to why we did it and then the product and then how it supports that. And most of our actual advertising happens on social media. So our actual paid advertisement is Facebook and Instagram ads for the most part. And you just don't have the time or you don't have people's attention to really tell that story. And so we've been going through a pretty big trial and error process to try to market, especially on social media without using cliches, without losing people along the way. And without what I say, it's losing our soul. So it's tricky and the way, I'm not saying we've found the secret sauce yet, but there's some things that we've figured out that at least I feel comfortable with because I work with external marketing firms and I work with people that typically, especially in the Kickstarter and crowdfunding, you see a lot of all caps and this is the best jacket that's ever been built and this, it's very subjective of hyperbole. (12:00): And so I work with them and say, Hey, we don't want to do that. And they look at me like, oh, well you just kind of cut off our left arm. But what we found is that we can find the true value propositions for what we do that aren't subjective. So you don't say best, but we say this is really good. You say high quality, which is somewhat subjective, but I think it's objective if you really kind of know the product, we talk about the features that people are going to get, why they're good. And importantly, like I said, you don't have a chance to put down all 15 features of a pair of pants on a social media ad, but we will make several different versions that key in on one feature with an image of that, (12:48): And we'll test those. And we've kind of seen which things resonate with people so you don't have the attention span to tell 'em all about it, but you can test putting out different value propositions like these pants fit, right, talk about fit, talk about material, they're sustainable, talk about organic cotton, recycled polyester, see if that resonates. Talk about articulation movement. Gus did CRO articulated knee. And so we can really still talk about honest features, honest value proposition without losing people's attention by kind of narrowing what we talk about on each individual ad or campaign. I have some rules, I'd say we don't use all caps, we don't use hyperbole. We try not to say best or subjective terms because the best pair of pants to me or you may not be the best pair of pants is someone living in New York City. And then the other thing we've found too is just on a side note, not as much about losing your soul is showing product detail. (13:46): And especially in social media advertising closeup shots has been extremely powerful and we've been baffled sometimes We've gone through several rounds of studio shots for our products, and the first round was not very good. Lighting was kind of blown out. It was a version one of the pant, and we'd even change it since then. But we had this ad that was just killing it and it was just this blown out studio shot of the back pocket. And we were like, why is this working so well? Our hypothesis is that it showed the stitch work, it showed the detail, it showed the fabric texture, and those are all things that are really hard to see on online shopping. (14:23): How many times have you bought something, a jacket or a pair of pants or even a backpack or a piece of gear that looked great in the shot, but you can't zoom in, you can't look at it, and you get in and you're like, ah, it feels cheap. The stitch works bad, this seam is sloppy. And so I think what we keyed in on there is that showing that detail gives people a lot of confidence in the product, even though that ad didn't even show the pants as a whole back pocket and it's been the best we've had. So we've learned some of these things along the way, which is choose your value proposition. You can't get 'em all out there. Showing detail helps and don't use all caps and don't say, this is the best thing ever. I want to get to the point where we can just say we make good pants. And kind of like the Ron Swanson approach to marketing. It's like we make good pants. If you need good pants, we're here for you.", "token_estimate": 1122, "speakers": ["Andrew Gibbs-Dabney"], "start_timestamp": "10:49", "end_timestamp": "10:49", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "25c6d4cd-6511-440f-9252-a9ee47ff51df", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 8, "content": "Cole Heilborn (15:17): So yeah, it's interesting the reaction you had from that super detailed product shot. Why do you think you got that reaction? Why do you think your audience was interested in seeing the stitching and the fabric up close in an ad on social media? I could see that performing well in an e-commerce page where they're about to click buy now, but seeing that on social media where you're not necessarily looking for a pair of pants, why do you think that resonates?", "token_estimate": 121, "speakers": ["Cole Heilborn"], "start_timestamp": "15:17", "end_timestamp": "15:17", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "38287baa-4890-4d12-8d0b-7193e5c3d3e1", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 9, "content": "Andrew Gibbs-Dabney (15:57): What works and doesn't work on social media? Marketing really sometimes just baffles me. But like I said before, I think it's mostly because people are getting a sense that maybe we are a high quality because we're confident in showing the details of what we build. And that's something, it goes back to having a low product count. And one thing we really do well is there's not a stitch or seam or detail on this pants that hasn't been analyzed and analyzed again and redone and kind of minutely tweaked, which by the way, factories are not huge fans of that, but they're willing to play ball, right? We've gone through, I don't know, at least 15 if not 20 iterations of these pants because I wear them every day. Most of my friends wear them every day now. And so I see them on myself, I see them on them, even if they're too kind to tell me. (16:48): I look at a pocket and I'm like, that's flaring a little too much. So the next time I'll say, Hey, let's take a half inch or a quarter inch of ease out of that pocket opening just to make sure that it doesn't flare when someone sits down. And what I think people are responding to with showing that detail is that attention to detail. They're getting some confidence that this isn't a drop shift item from China that 20 other vendors sell. This is something that was designed with intent and a company that cares about what they do. And so we try to sell that aspect too, which is we are really trying to make a quality product and we have a customer service team that's going to answer your call and we have this warranty that's going to stand behind it, kind of get over this. It's 2020. I don't trust anything barrier that a lot of people have towards new products, which I think is a healthy skepticism.\n\nCole Heilborn (17:41): I think it's warranted.\n\nAndrew Gibbs-Dabney (17:43): It is. And I'm not saying they shouldn't have it. We have to fight, especially if we're not going to play the game a lot of those companies would like with the all caps and with the ridiculous call to actions and everything like that, we get to really break through that in a way that feels okay to us.", "token_estimate": 543, "speakers": ["Andrew Gibbs-Dabney", "Cole Heilborn"], "start_timestamp": "15:57", "end_timestamp": "17:43", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "9c268cd8-b299-43ee-a4b8-f59b81be35ad", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 10, "content": "Cole Heilborn (18:02): Yeah, interesting. So when you were outlining your, I guess we'll call 'em Andrew's rules of marketing, you said you've outlined those because you don't want to lose your soul when it comes to the marketing work you guys do. Have you lost it before?\n\nAndrew Gibbs-Dabney (18:19): No, I don't really think so. It's just more I'm been an outdoor consumer. I've been a cut consumer period for my whole life. We all are, and I'm just not entirely happy with the way the whole, I'm not going to say industry products in general are progressing in the world. There's just so much stuff being built and every niche, even the niches within the niches are being filled. And a lot of the times it's not because it's a great product, it's just because it's an okay product and it was built specifically just to make money out of that hole in the market. And then it was marketed by a firm that's good at marketing. And so that kind of thing. And we want to make something new. We want to make something new that deserves to exist, and if it doesn't, we don't really want to do it. (19:08): And so like I said, I don't think I've lost it now or lost it in the past. The previous brand I worked for Fayette Hill, we tried our best to market responsibly there too. We mainly made a t-shirt, which most people don't need another T-shirt, but we tried to do everything that we could to make it as good as possible. So made in USA organic cotton, recycled polyester, we did community support, we did nonprofit support, we did events. That was kind of our way of saying, Hey, we're making something that people maybe don't need, but we're going to try to atone for that. (19:40): And going into this, I didn't even really feel like that was even the best way to do it. I really wanted to make a product that deserves to exist on its head that for the sake of it, if nothing else, no brand, no anything, no extra support for the community, no nonprofit or anything, which we're going to do and we do do, but I want that product to exist by nature of people see it's high quality and they end up using it and get back. You mentioned sustainability and I'm passionate about it and I skipped over that for marketing talk, but that's really my chief view and our chief view it lives in of sustainability is just build things that deserves to exist. Don't build things just because you think you kind of have a hole in your lineup and you need to fill it, right? I guarantee you someone else makes that product. If you're just making a hat to make a hat, it's just, and I'm not going to paint myself into a corner and make a bunch of enemies. (20:46): There is value to creating income for yourself. There's value in creating a company and jobs, and that is inherently something that we need in this society. So I'm not demonizing people for just making your brand to make money, but what is it that makes what you're doing worth it? And especially environmentally. So our view, like I said, is the product needs to deserve to exist, have some sort of use, but then falling right on the heel that if you're going to make it start in the design process and make it durable, start in the design process and make it versatile and then follow that up with a real warranty and stand by your products and help that product stay in lifecycle longer. Because the most durable, the most sustainable product that exists is the one that already exists. (21:38): So durability is really the most sustainable thing aspect of any product. It comes before, whether it's made with hemp or organic cotton or recycled polyester, it doesn't really matter. Okay, I will say this, it matters a little bit, but more than what a material is made out of making it in the first place is going to use a ton of carbon. So if you're going to make a product, right, and you have to weigh something that's made from an eco-friendly material, it's going to last half as long for something that's made from a raw virgin material that's going to last twice as long, you're going to use a lot of carbon getting either one of those to market. You got to ship it, you got to make it, you got to do all the things to service it and get it to the end consumer. So personally, I think making the more durable product is better, and that's what we launched on, but with the intention of following that up with environmentally friendly materials. So we moved to organic cotton, recycled polyester. Like I said, everything, all those products are listed out earlier are either organic or recycled for the vast majority of their content. (22:38): And then we're also going as far as to, we actually ditched poly bags for this season, so we're actually going to a roll packing. So we got this paper twine and a recycled paper hang tag. Oh, cool. Wrapped up. We ditched everything, plastic and everything, single use out of that process. Everything's recycled and recyclable. But that's after we earn those things as a startup through getting out into the market. And that's all somewhat subordinate to me, to making a durable product and making something that's repairable and also helping people get that done. We have an infrastructure to do it right, they can send it back for repair, but it's also educating the consumer and reaching the consumer that's going to buy with the intention of keeping something for a long time, keeping it in surface, wearing that same pair of pants, and if they have a rip in it, repair it. They may not be your office pants anymore or you're going out, but they're definitely still good yard work pants. They don't need to go in the trash. That's something that I'm very passionate about from a sustainability point of view is just this idea of don't build so much stuff and what you do make it durable. And that's just not what's going on in the grand scheme of things with product development,", "token_estimate": 1472, "speakers": ["Cole Heilborn", "Andrew Gibbs-Dabney"], "start_timestamp": "18:02", "end_timestamp": "18:19", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "f8667b98-44e9-45ce-923a-90eac63e1373", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 11, "content": "Cole Heilborn (23:54): How does that passion connect to what you said earlier about marketing responsibly? I feel like those are two kind of tangibles that are running parallel to each other and are connected in various ways. How does that connect for you?\n\nAndrew Gibbs-Dabney (24:13): I mean, it's in our DNA, I think it's in a lot of the outdoor industry companies. DNA too is just the way in which you get your value proposition out. And if your value proposition is sustainability and durability, I don't think you're going to get that out correctly or authentically to use a buzzword in the industry or even convincingly if it just looks like every other piece of crap that you see on Instagram feed. From a messaging point of view, I think there's people out there that are into long form content. There's people out there that want to read and research the details. There's people out there that want to look behind the scenes of a company and figure out who it's and what they stand for. And I think that there's just a little bit of a difference in the way that you have to market to reach that person to break through that. (25:04): Like I said, that initial barrier of this is all bs, right? And so we're figuring it out. I'm working with firms that do crowdfunding marketing, and we're having to do a little bit of that stuff. They're like, there's some things we're going to do that you may not feel a hundred percent comfortable with, but we're keeping in mind everything you told us. I'm like, okay, we'll see if I see the ad and I like it, we'll have to talk. But so far it's working. And like I said, they do run parallel, but I think they're kind of one in the same. If you have an intention to do something a certain way and it's deep in the value of how you want the business to behave, and if it's part of the DNA, then it's going to flow through everything. It's going to flow through the product, it's going to flow through the marketing, it's going to flow through the messaging, it's going to flow through your operations.", "token_estimate": 512, "speakers": ["Cole Heilborn", "Andrew Gibbs-Dabney"], "start_timestamp": "23:54", "end_timestamp": "24:13", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "7ea984a4-662e-48e3-b65f-b399a41d0d89", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 12, "content": "Cole Heilborn (25:55): Yeah, well said. That makes a lot of sense. Where would you like to see, well, lemme back up. Lemme rephrase that. How would you like to see advertising and marketing change, not just in the outdoor space, but in the, I don't know, just the world and commerce?\n\nAndrew Gibbs-Dabney (26:20): That's a good question. Hence the long pause. If I could wrinkle my nose and give my wish, there'd just be less of it, but that's not going to happen. So I'll just kind of put it back to sustainability. I would like to see more authentic values-based marketing from companies talking about what they're doing to actually address environmental issues and sustainability and clean up their act. And that's not just outdoor industry, that's all industries. So I'd like to see that not just from, like I said, value when people know your values are, but it gets it more to the mainstream. And I think what it will do and is happening is it's somewhat taking the onus of responsibility for environmental change off of the individual and onto the corporation and the company. And what I mean by that is everybody, I try to live a sustainable life individually, but individuals acting sustainably and using their single use straw versus a plastic one contributing the most to global climate change. It's actually companies and it's it's companies. And so that's not to say the individual consumer doesn't have a place in this. I think what the individual consumer does have the job to do is vote with their wallet. And if companies put out their views, what they're actually doing, not just greenwashing, but what they're actually doing to change their ways and act responsibly and environmentally and consumers then follow that up by voting with their wallet and buying their products, then we can actually affect change at the top. (28:05): So just to clarify, I don't think people should start using plastic bags and ditch their aluminum straw, but because that's also, like I said, kind of voting with your wallet, but I do think that the narrative and the responsibility needs to be shifted more to the top from the bottom because that's where the real change is going to happen. I think people can help make that happen.", "token_estimate": 559, "speakers": ["Cole Heilborn", "Andrew Gibbs-Dabney"], "start_timestamp": "25:55", "end_timestamp": "26:20", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "c89445ff-5e83-4f1b-a814-a1ba2b7318fe", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 13, "content": "Cole Heilborn (28:27): This is a nice segue to plug a previous episode that when this episode comes out, this other episode will be out. We did an interview with Austin Whitman over at Climate Neutral and he talks a lot about this topic and it's really educational if you guys want to dive in deeper and learn more about what individuals can do and what nonprofits are working on to try and help brands realize their climate impact and quantify that. So go check that out if you want to learn more.\n\nAndrew Gibbs-Dabney (28:59): Very cool. I'll listen to that one when it's up.\n\nCole Heilborn (29:01): Yeah, so I think what you're talking about is, it's interesting because I have the same belief in that when you look at marketing, there's just so much clutter and junk out there, whether it's video or photos or blogs or billboards or commercials, it is just everywhere. And I feel like as we create more places like social media, we add more channels. What we're doing is just creating more avenues for marketers to get their messaging out there. And I feel like we've hit a point now where the only way you can compete is either have go really high quality or you have to go just constant messaging, low quality, high volume. What's your take on, I guess that concept?", "token_estimate": 318, "speakers": ["Cole Heilborn", "Andrew Gibbs-Dabney"], "start_timestamp": "28:27", "end_timestamp": "29:01", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "b9890cb3-178b-493e-a7bd-d4fb827ee3a4", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 14, "content": "Andrew Gibbs-Dabney (29:57): I mean, I think no matter what product you make, I think you have to market it. There's this kind of old stereotype of you're either a product guy or you're a marketing guy, or you're a product company or you're a marketing company. And there's this idea that if you're an artisan, if you're a craftsman, if you really love your product, that marketing is somehow unholy. It's dirty. And I don't think that they go hand in hand. And your marketing we've talked about before doesn't have to be dirty, doesn't have, you don't have to lose your soul to do it. And I think that now at least to start, unless you have just, I will qualify this, different levels of funding at the start can allow you to do different go-to-market strategies and launch a brand or a product. But social media marketing and kind of pay-per-click marketing and things like that have really lowered the bar to entry for a brand to get out into the market and compete directly head to head with the biggest players out there. (30:58): And I think that that is both a good and bad thing. It's led to this rise of a bunch of brands that probably shouldn't be around, but it also lets somebody that has a good product get in the market. And I think you have to play the game a little bit. You make a great product, how are you going to get it into people's hands the first few times? So you have this kind of easily accessible outlet to do that through social media and Facebook, and you can very cost effectively market. Now, you can also waste a lot of money. I'd recommend people hiring a professional if you're not very good at this, but you can get your part out there and then you can start to do the things that let you spread by word of mouth that is delivering a good product that delights people. (31:40): That's like number one, you get the sale, they get a product and it's better than they thought that it was. They're going to tell their friend about it. That's when you get into this, no one's going to grow. And if your business only relies on social media like return on ad spend, you're going to go broke. You're never going to grow organically. But if you have that and then you follow it up with a good product, and then the next step is you actually have the systems in place, so the people, or at least the intention to stand behind that product. So say you send the wrong size or does it fit or it happens, there's a production issue with the product and they contact you and they get a real response from a real person and you help 'em figure it out. That's how you kind of grow that, like you say, quality or mass marketing. (32:28): There's somewhere in between. You can use the marketing channels, but you actually follow it up with quality and you'll, people know that you are a real person and you're a real company and you have a good product. And it's funny, I used to do customer service at the last company I worked for. I started the whole process and everything. There's an inverse relationship between how mad someone is when they initially email you and how big of a supporter they'll be if you take care of them. The more expletives and curt sentences that were in the email and the length of it, if you take the time to actually kind of address those things and get that person taken care of, no matter what, it takes the bigger fan, they're going to be coming out the other end. Totally. And that's something that's like, I think in the outdoor industry, it's understood. (33:11): The outdoor industry cannot be faulted for customer service practices. Usually that's likes just the water we swim and you got to have great customer service, but across just general consumer goods, that is not the case. We get emails from people that are just so rude because, and it's not because the people are rude, it's because that's typically the hat they had to put on to get a response. The more angry you are, the better you get taken care of. It's like the cable company rule or something like that and one kind of courteous response, that whole demeanor goes away and it turns into a real person. So anyway, that was a long answer to your question, but I don't think it's as black and white as the initial proposition. I think that there's a way to play the game well.", "token_estimate": 1075, "speakers": ["Andrew Gibbs-Dabney"], "start_timestamp": "29:57", "end_timestamp": "29:57", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "c58f8e66-abef-449c-b032-38552856d870", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 15, "content": "Cole Heilborn (34:00): Yeah, fair enough. We're about out of time for today, but one of my last questions for you. What's your hope for the future of Lipson? Your two years in, what do you hope for two more years or the next 10 years?\n\nAndrew Gibbs-Dabney (34:15): Yeah, we just launched wholesale side of the business and brought on some really great independent reps. So we're looking for really great retailers. So my hope as someone that's lived and breathed the outdoor industry for as a consumer and then someone on the other side. For most of my life, I want to see this in the best stores around the country, the ones, the independent shops, specialty shops that really have that great floor staff that knows they're talking about that live the lifestyle that help people buy the best products. That's where we want to be from a product standpoint. We're going to slowly expand what we do. We're not going to stay in pants forever, but we're going to do that until we feel like we need to move out of that space into the next thing that doesn't exist in the way in which that we'd like to see it exist. (35:01): And so my goal is to make the absolute best, and I'll use it now because subjective, and it's my subjection or my point of view, the best products in the industry. When I say that, like I said, it's subjective, what that means to me is that they're durable, they're extremely versatile, they're comfortable and they fit well, and you turn 'em inside out and you're not let down. So there's refinement, and these are the qualities that we look for when we design and as we go through the prototyping process. If they don't hit that, then we don't release it. So in two years and five years, we want to be a, if not the leading brand in those categories, right, in the outdoor industry. But if someone's looking through the lens of durability and versatility and refinement and fit, it lives in to be synonymous with those things. And that's where we're headed, I think.\n\nCole Heilborn (35:52): Yeah. Yeah. Well, I'm excited for you guys. If people want to follow along, if they want to find more, learn more about the products you have to offer, where can they go to check 'em out?", "token_estimate": 550, "speakers": ["Cole Heilborn", "Andrew Gibbs-Dabney"], "start_timestamp": "34:00", "end_timestamp": "35:52", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "61952705-63c4-4331-acb6-2a5efc4e3be9", "episode_id": "babd1730-0a6c-4bbf-8ea0-8e45008c8505", "cms_item_id": "68225dfc7bb476527f8c4842", "chunk_index": 16, "content": "Andrew Gibbs-Dabney (36:04): Our website, you can go to lives in.com l live VSN. (36:08): It'll actually redirect you to lives in designs.com. But same thing. And then on Instagram, at Lives in Designs and in our Instagram, we're working on it, I'm the one who posts almost everything. And because of that, we show some behind the scenes. It's not just aspirational marketing. You can get that anywhere. But what we do show is the trips we go on, the part development, we do a lot of polls to say, Hey, this is the new colors. We're thinking about, Hey, what sizes do you wear? The sizing of our Flex Game fans is basically based on Instagram poll responses. So people can really, I think, get be part of this and see an unvarnished behind the scenes side of the brand and not just aspirational marketing, which we do as well, but pretty pictures are good, but we show everything.\n\nCole Heilborn (36:58): They're good when you back 'em up with the behind the scenes stuff.\n\nAndrew Gibbs-Dabney (37:03): Yeah.\n\nCole Heilborn (37:03): Cool. Alright, awesome. Well, thanks so much, Andrew. It's been good chatting. Have a good rest of your day.\n\nAndrew Gibbs-Dabney (37:09): Yeah, thank you. It's\n\nCole Heilborn (37:10): Been great. Alright, take care. Thanks again for listening to this episode. If you enjoyed it, please consider sharing it with a friend or leaving us a review on Apple. Also, remember to check out Darby Communications. If you're looking for a great PR and marketing team, go ahead and find 'em at darby communications.com.", "token_estimate": 385, "speakers": ["Andrew Gibbs-Dabney", "Cole Heilborn"], "start_timestamp": "36:04", "end_timestamp": "37:10", "podcast_index": 33, "episode_name": "Ep 33: Andrew Gibbs-Dabney | More with Less| LIVSN Desig‪n‬", "slug": "ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "web_url": "https://www.portsidepro.com/podcast-feed/ep-33-andrew-gibbs-dabney-more-with-less-livsn-design", "guest_name": "Andrew Gibbs-Dabney", "guest_title": "Founder, LIVSN Designs", "categories": [], "short_description": "\"If your business only relies on social media, you're going to go broke. You need a good product.\"", "podcast_length": "44:55"}, {"id": "066f5a44-1744-406e-aea2-42366ef5b278", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 0, "content": "Cole Heilborn (00:02): Welcome to the Backcountry Marketing Podcast. My name is Cole Hilborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Before we jump into today's episode, I wanted to talk about Darby Communications there. They're our presenting sponsor for this episode. I've gotten to know them over the last few months as they've helped me with some PR and marketing for this podcast. The Darby com team has designed their process around my needs, combining a people first mindset with an analytical data-driven approach. Today's business world moves fast, but the Darby com team has taken the time to truly get to know me and understand my goals. They've been a great partner to collaborate with, and I'm really impressed with their well-rounded approach that generate real results that actually help bring this podcast to more ears. If you're in the market for a great PR team in the outdoor wellness and fitness industry, go ahead and check 'em out@darbycommunications.com. (01:18): Welcome to the Backcountry Marketing Podcast. Today I'm sitting down with Patrick Tolles, the senior manager of Brand Communications and Sports Marketing at Adidas Outdoor. Patrick, how are you?\n\nPatrick Tullos (01:27): Oh, doing well. Thanks for having me. Really excited to be here.\n\nCole Heilborn (01:31): Yeah, thanks for joining. You're not too far away, just down south in Portland.\n\nPatrick Tullos (01:36): Yeah, yeah. I live here in North Portland, so on the north side of the river here and nice and smoky today. Unfortunately, those fires are pretty crazy. But yeah, just down south.", "token_estimate": 510, "speakers": ["Cole Heilborn", "Patrick Tullos"], "start_timestamp": "00:02", "end_timestamp": "01:36", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "ec7dd8c7-b6a0-4108-9a7c-78039db20634", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 1, "content": "Cole Heilborn (01:48): I was talking with a friend earlier this week and we were talking about some of the major cities on the northwest and what we liked about them and what we didn't like about them, and the conclusion we came to about Portland was that you guys have so many donut shops. It's such a great place to visit.\n\nPatrick Tullos (02:02): That's very true. Yeah, as a donut addict myself, it's pretty nice here, for sure. Yeah. Yeah. Gets me through the winners. Absolutely. I'm from Colorado originally, so the winners here. Sometimes I need some of that comfort food.\n\nCole Heilborn (02:19): Well, and that also is a good motivation, I suppose, to go out on a run and get a little exercise in too after a dozen donuts.\n\nPatrick Tullos (02:27): Yeah, absolutely.\n\nCole Heilborn (02:30): Well, so tell us a little bit about your job. You got a long title, can you break that down and what that means?\n\nPatrick Tullos (02:37): Yeah, I mean, the simplistic version of it is I look after any of the brand side of the business for Adidas within the outdoor space. So we kind of break that off into three different prongs. So there's TerraX, which is our performance technical on the mountain product for trail running, hiking, and snow. And then five 10, which I'm sure a lot of the listeners know, but is a brand that Adidas purchased about 10 years ago that's focused on mountain biking and climbing footwear. Been around for 30 plus years, born and raised in the Yosemite Valley. And then we also are the center of excellence for all jackets within the brand. So whether it's like a sideline insulated jacket or just a basic rain jacket, we look after that and work with the other businesses to be able to make those work into the other sports as well that we do.\n\nCole Heilborn (03:35): Okay, gotcha. So you interact with all of those. What parts do you have your hands on?\n\nPatrick Tullos (03:41): So anything from media and advertising, the creative here in North America, and then all of our athletes grassroots events. So pretty much the whole gamut from front to back. When you think of marketing here in North America,", "token_estimate": 534, "speakers": ["Cole Heilborn", "Patrick Tullos"], "start_timestamp": "01:48", "end_timestamp": "03:41", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "18034f87-95bc-42d9-8cb8-3c72e15f3790", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 2, "content": "Cole Heilborn (04:00): Right on. That sounds like fun. It may be a little overwhelming at some times.\n\nPatrick Tullos (04:04): Oh, man, it's been a blast. I mean, I've been at Adidas for about five years, but in this role for about a year and a half. And we were actually a brand new business unit here in Portland, so I was completely alone. We were absorbing the business from a distributor and kind of got to spearhead this over the last year and a half, which has been an absolute blast, but absolutely exhausting too. So we still have a long way to go, but man, it's been fun to have that entrepreneurial mindset in such a big brand like Adidas too.\n\nCole Heilborn (04:40): Yeah, no kidding. So before we jump into today's topic, I'd be curious if you can give us a little bit of a background on where you came from, how you got to where you are now, because Adidas, you guys are a killer brand, and there's a lot of people out there who I think would love to know how do I wear a pair of Adidas, go from wearing a pair of shoes to then working on the brand and working on the brand side. So kind of break down that progression for us.", "token_estimate": 285, "speakers": ["Cole Heilborn", "Patrick Tullos"], "start_timestamp": "04:00", "end_timestamp": "04:40", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "965615e2-802a-4c5a-8189-6c10234eccd3", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 3, "content": "Patrick Tullos (05:08): Yeah, I mean, similar to a lot of the people you've had on the podcast, I think I have a very non-traditional business background, but I think that's also more and more traditional within the outdoor space too. I mean, the average person that goes to school gets their undergrad goes to graduate school than finds an internship, gets a job in the outdoor industry, is there for sure. But something I love about the outdoor industry is allows people like me who's really bad at school to be able to get in and kind of work on your passion too. So my roots, like I said, I'm from Colorado, so I grew up in a small mountain town there called Conifer and was in an outdoors family. Everything we did was outside even to just hanging out all the way through to climbing and snowboarding and just generally playing around on rocks. (06:05): So that spearheaded where my direction was going to be headed, whether I like it or not. And in high school, I started working at some snowboard shops, and after high school I was trying to figure out what I wanted to do, and I had enrolled in college and was actually doing pretty well, which was new for me in school for sure. But halfway through the semester, a sales rep came into the shop and I'd kind of become friends with him, and we were just talking and he just out of the blue kind of brought up like, Hey, my sub rep actually just left. Would you be interested in working with me? So next thing I know, I was pretty young and working a dream job, managing some real business, and it was pre 2008, so the industry was just booming and there was a lot of fun trips and fun sales meetings, and I got to do that for a number of years. (07:07): And then a really smart young person, I saw the 2008 financial crisis and I'm like, oh, this would be a great time to start my own agency. So I actually left and I ended up starting my own agency and did that for a number of years. And the Rockies at the end, we were looking after about 15 brands and the skates, snow and outdoor space, everything from footwear and apparel to hard goods and accessories. And from there I moved in-house with a couple of the brands that I was working with and managed their North American sales. So made the move out to LA and was there for a couple of years. And LA was just not my thing. I wasn't SoCal built for sure, and ended up getting headhunted into Adidas. And I've been there for about five years. So I've had a number of roles there. Before outdoor, I was based in the action sports business unit, and I looked after global events and retail and digital activation for skateboarding and", "token_estimate": 661, "speakers": ["Patrick Tullos"], "start_timestamp": "05:08", "end_timestamp": "05:08", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "94148298-58fc-4907-89a1-0611ca88eab5", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 4, "content": "Cole Heilborn (08:13): Snowboarding. And you were there for four years, and then it's only been this last year that you've transitioned\n\nPatrick Tullos (08:20): About a year and a half, a little over a year and a half now, been in this outdoor role.\n\nCole Heilborn (08:25): Okay. Yeah. What's that been like?\n\nPatrick Tullos (08:28): Yeah, it's been so fun. I mean, I also have a bit of an entrepreneurial background from starting my agency, and then I also owned a liquor store with a business partner in Denver for a little bit, so as a side hustle project. So I definitely have that entrepreneurial blood running through my veins and sometimes working at such a large corporate brand, there's so many pieces and sometimes you miss that. So frankly, it's been really cool to be able to build this from scratch with someone else's money and kind of do it in a way that myself and the rest of our team really kind of envision it. But it's absolutely been not without its headwinds for sure. We've been learning a lot and a lot of trial by fire and a lot of adjustment on the go. And this year has definitely tested that for sure. But yeah, it's been so fun. We have a team of 12 now here in Portland that work on the outdoor business as a whole, and it's a great group of people that are extremely smart and humble and really are just excited to get stuff done. Yeah, it's been fun. I think having the outdoor business set up in Portland is going to allow us to be able to be a lot more relevant in the North American market where Adidas is less mature in the outdoor space as opposed to in Asia or Europe where the Adidas outdoor brands are a lot more mature, for sure.\n\nCole Heilborn (10:10): Yeah, man. Talk about having a good team that helps you do your job, that makes a world of a difference.\n\nPatrick Tullos (10:15): It's everything. It's so everything. I mean, you could have the best job in the world, and if the people surrounding you are not one fun to work with and also challenge you to be better, it doesn't even matter if you have the best job in the world, it's not going to do it.", "token_estimate": 525, "speakers": ["Cole Heilborn", "Patrick Tullos"], "start_timestamp": "08:13", "end_timestamp": "10:15", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "1abbe8c9-d9b8-4faf-8a2f-541ca37a3057", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 5, "content": "Cole Heilborn (10:33): So has that team of 12 always been a part of the group, or how has that team been built?\n\nPatrick Tullos (10:41): Yeah, so like I said, we absorbed the business from a distributor. So there was a mix of pulling in some of the employees, specifically our sales team from the distributor. So it was a company called Agron that was distributing Adidas outdoor in North America before. And we did absorb that sales team in the outside sales reps, but the internal business, so our go-to-market team and our merchandisers, and then the comms and brand team, that's a bit of a hodgepodge all over the place. So someone like Devo Derby, who's our athlete manager here for North America for trail run, bike and climb, he was actually an athlete of ours and a grassroots ambassador of the outdoor brands. And we had met him in the transition and he's just so impressive. So we actually pulled him in. And then there's also veterans, like my coworker Aliza, who's been at Adidas for 13 years, something like that. And she's my counterpart on the merch side. So she looks after all the products here in North America, and she actually started her career at Adidas as an intern in the outdoor business unit and has circled back around to now leading the product side for North America.\n\nCole Heilborn (11:55): So there you go. She's one of those few examples.\n\nPatrick Tullos (11:58): Yeah, definitely. Definitely. Yeah.\n\nCole Heilborn (12:02): So what has that been like for you personally as you've been working through this last year and a half of this? It sounds like this very complicated, sometimes arduous task of blending and doing this huge transition.", "token_estimate": 418, "speakers": ["Cole Heilborn", "Patrick Tullos"], "start_timestamp": "10:33", "end_timestamp": "12:02", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "f936cc3c-ce48-48df-bd28-dd22cc19827e", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 6, "content": "Patrick Tullos (12:17): Yeah. Yeah. I mean, the last year and a half luckily came after the year and a half before that. And I know we talked, and something that I'm really passionate about is just mental health awareness. And I also think it's just so ironic in our space that the more people I talk to within the industry and network with, the more we're all overworked and taxing our mental health when we work in an industry that really should be able to allow you to turn off and adjust and be able to recharge. But I think that comes with the territory of being in a world that you care about so much. It's kind of hard to turn that off. So about three years ago when I was in the action sports business unit, I was traveling a lot internationally, looking after events globally and just running on all cylinders. (13:14): And ultimately it came to a point where I was go, go, go, and it came the holiday time and I didn't know what to do. I had two weeks free at the end of the year. I was kind of just like I could do whatever I wanted. I could go up to Mount Hood and go skinning or just go for a long run, and I was paralyzed. I couldn't do anything. And I started to have these daily panic attacks that just completely paralyzed me. And it was such a weird journey for me because although I've always been an anxious person and I've always had anxiety, it wasn't to a point that it was affecting my daily life. And then when we came back on to normal schedule after the first of the year, I was supposed to go to Germany for some meetings and I had packed my bags, and I just remember sitting on the couch looking at my packed bag just thinking, you couldn't pay me a million dollars to get on this plane. (14:22): I was just terrified of nothing. And that ultimately kind of made me retake a look at my life and relook at how crazy is this that I'm feeling this way from being so burnt out, but also just neglecting my mental health in this world that should be the most fun. So ended up making a lot of lifestyle changes that I don't think if I would've made before or I know for sure if I didn't make those lifestyle changes before this last year and a half would not have been, it wouldn't have been possible for me to do and do in the average way that I've done it, I guess.", "token_estimate": 573, "speakers": ["Patrick Tullos"], "start_timestamp": "12:17", "end_timestamp": "12:17", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "4813b033-6415-4408-850b-cf5e0329847b", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 7, "content": "Cole Heilborn (15:09): Yeah. Wow, man, I feel like the hardest challenges are the ones where they're about yourself and they're internal and you have to ask tough questions when they're external, it seems like they're way easier to solve. How did you know? So you, you're in that two week period where you're at home, you're feeling lost. How did you begin to even think about or process or structure the framework to have this conversation with yourself and start asking yourself these questions? I think sometimes that's a really hard thing to do is just to even get yourself to that point. Does that make sense?", "token_estimate": 154, "speakers": ["Cole Heilborn"], "start_timestamp": "15:09", "end_timestamp": "15:09", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "a771dea6-483d-4563-ba81-9a431f07cc16", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 8, "content": "Patrick Tullos (15:48): Yeah, yeah, for sure. It makes sense. And I think it's a really good question. I think it took a long time for me to really take a look at it. I think a long time, I'm, for a long time, I was sitting there, okay, I need to drink less caffeine or no caffeine. And so I stopped drinking caffeine and I was like, okay, I need to stop drinking. It's not going away. I need to stop drinking alcohol. So I stopped drinking alcohol and I was like, oh, I need to exercise more. And so I exercise more and it just wouldn't go away. And ultimately all those lifestyle changes are good, but they're putting a bandaid on a shotgun wound sometimes. And there was a moment that I was somewhere, I don't even remember where, but I was talking to one of the athletes on the skateboard team, and she has become a very good friend of mine, and she actually brought it up to me of like, Hey, are you okay? You seem really stressed. Are you good? (16:54): I just unloaded on her and was like, it's been super tough few months. This was probably four or five months after that come to Jesus moment where I couldn't get on the plane. And she was like, Hey, I deal with that too. I have panic attacks all the time, and here's what I've done that works for me and here's who I talk to and how I talk to them. And I think that was the moment that this woman who is this powerhouse within the skateboard world and was essentially changing the way that consumers and women were looking at skateboarding, and she had this too, and it kind of made it okay, and it sounds so cliche, and I think there's a lot of things coming out that speak to professional athletes dealing with this or people at higher levels like executive levels dealing with anxiety and different mental health illness. But I think it's just so important to be able to open up and just say those things to a person to person level because it actually connects you and humanizes you. So I think that was the first moment where I was like, okay, I need some help. I can't just out-train this or I can't out vitamin this. All those things are good, but I needed something to help me get through it and continue to get through it as well.", "token_estimate": 550, "speakers": ["Patrick Tullos"], "start_timestamp": "15:48", "end_timestamp": "15:48", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "2daf2eb7-70e0-46f7-ad15-5e77fea5f3f4", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 9, "content": "Cole Heilborn (18:25): Yeah,\n\nPatrick Tullos (18:25): Yeah.\n\nCole Heilborn (18:27): Or as we like to in today's culture, just outwork whatever problem it is.\n\nPatrick Tullos (18:32): Oh, for sure. And I was a hundred percent guilty of that, and it has benefited me for sure, but it was also a root of my anxiety as well, of just keeping and diving into that mentality of being anxious that you're not good enough or being, I always felt indebted because I felt so thankful to be in this industry. So I was like, I always need to work so hard for this industry and the brands that I work for, but ultimately the culture because it's changed my life. But once again, if you're not looking after your mental health, that only goes so far and you can't do things. So I guess to circle all the way back to your question about how the last year and a half has been, honestly, the last year and a half have been probably the most that I've worked in my career. (19:27): I've been on the road in 2019, I think I was on the road 200 plus days, but I took the time and I was also the 20 19, 20 20 is wash, but 2019 was the first year in a long time that I had snowboarded more than 20 days. I was climbing more than I'd ever climbed. I was exercising the most I had and was kind of felt like a kid in a candy shop again, back in this world, which I know some people are really good at it, and I look at some leaders within the industry and view them as mentors and activity where they're out getting it all the time. But I think a lot of people too just are trying to outwork themselves. And that can be a really scary thing, I think.\n\nCole Heilborn (20:20): Yeah. Were you able to figure out where the source of the anxiety came from? I feel like that's a lot of the battle is just trying to understand why am I feeling this way?", "token_estimate": 455, "speakers": ["Cole Heilborn", "Patrick Tullos"], "start_timestamp": "18:25", "end_timestamp": "20:20", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "d490b03d-460f-4f4e-90d3-b135542e3333", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 10, "content": "Patrick Tullos (20:31): I mean serotonin for sure, just a general lack of serotonin for me. But yeah, I mean, I think it was a mix of a lot of things. I think it was just kind of a little of this and a little that, and it added up to just overflowing the pot. I don't think when some, I have generalized anxiety disorder, it's an actual illness I have, so there's things that exacerbate that, but there's not things that it's caused because it is that, and that's been a huge shift in my mentality as well, of if something happens in my personal life or in my work life, it might cause a moment of anxiety, but that's different than having anxiety as a whole too. So I don't know if that answers your question, but Yeah.\n\nCole Heilborn (21:31): Yeah. No, I think that does what I find really interesting in today's state, or I guess in just today's culture, mental health is, it's a really interesting topic. I was actually in advance of this call just doing research on mental health in American culture and British culture and the anxiety and depression are rising to levels that they've never been before in today's society, but it's still such a topic that we're not sure how to talk about, we don't want to address. And I'm hoping, why do you think that is? And how is that for you when you kind of address the issue, you realize the issue and then you realize what society, what you perceive they might be thinking about you?", "token_estimate": 358, "speakers": ["Patrick Tullos", "Cole Heilborn"], "start_timestamp": "20:31", "end_timestamp": "21:31", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "3e48923f-05ba-4b1c-b4ea-2dc2130533f2", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 11, "content": "Patrick Tullos (22:24): Yeah, I think a big root starts at childhood and we position performance culture and then also how we performance, excuse me, how we position, how we position priorities in life. And there's a ton of statistics like kids spend more time indoors than prisoners and that adults are spending 95% of their time indoors. And I definitely believe that being under the sky up in the mountains on a trail, whatever it is, is amazing medicine. And I think getting kids outdoors too is going to be really important as the next generation grows, not only for the business to be able to continue to boom and get people into the sports and buying the stuff, but also just from a mental health aspect as well. And then the other side of that is that performance culture and the us, and I can't speak to England as much, but the US is obviously so rat race driven. (23:39): And I think there's some beauty in certain cultures like climbing for instance, this dirt bag mentality that it's more about your accomplishments than the materialist side of it. But even that, I think can have its downfalls where it's still performance driven and you're constantly seeking to be that the top. And I think we as a culture and we as an industry have to find a middle ground to say it's okay to people to get outdoors and enjoy it and still work hard, but you don't have to work so hard that you're not getting outdoors too. And (24:25): My European counterparts do it right, for sure. I mean with the amount of time that they take off and the bank holidays that they get and everything else. So I think it's just also just a cultural shift for the us and a lot of our industry too is freelance. So it's like you have the hustle and if you're making money, you got to be constantly having that brain switched on and thinking about things, whether you're a videographer or a designer or whatever. You're constantly out there and it's so hard to turn it off and just enjoy. And I think with people with a predisposition to mental health problems, you have to learn to turn it off or else you won't be able to turn it off.", "token_estimate": 530, "speakers": ["Patrick Tullos"], "start_timestamp": "22:24", "end_timestamp": "22:24", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "5662d456-2644-4281-8144-c40493228d3d", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 12, "content": "Cole Heilborn (25:12): Yeah, that's a really good point. And I think that's the whole freelance market and what's the word, culture or industry is really interesting when it comes to work culture and how we work and speaking as someone in the film industry and someone there is that constant hustle. You always have to be finding that next job because next month, who knows if you're going to be able to pay rent or pay your mortgage.\n\nSpeaker 3 (25:41): Totally.\n\nCole Heilborn (25:42): And it's good to hear you talk about some of these things you've struggled with because there are things that I know I struggle with that I know other filmmakers, other buddies of mine struggle with. And I've got to say, when you can tell yourself that it's okay to not think about work, it's an amazing place. Being able to go out on the river and fish and not have to think about, where's my job going to come from tomorrow? It's so healthy. And oftentimes I've found that I come back to the office the next day and I have way more ideas, I'm way more energized, and the time that I lost, I've made up for in multiple other ways.\n\nPatrick Tullos (26:24): Right? Absolutely. I mean, nothing good and interesting happens at a desk, maybe this is, but I can give you anything I would put in a portfolio probably happened either while I was out doing the activity or at 2:00 AM over beers with a group of people that I love and trust and have good points of view too. So I definitely am a strong believer that getting out and about is what creates the best for the whole world too in our industry as a whole.\n\nCole Heilborn (27:02): Yeah. What role does marketing play in this perpetuation of the rat race? Because the outdoor industry is notorious for aspirational marketing. Let's make a film about some killer athlete pushing the boundaries, and then what does that do to people who watch it and then they get stuck down this unhealthy version of that life? What are your thoughts on that and how does that connect to your job and what you do?", "token_estimate": 508, "speakers": ["Cole Heilborn", "Speaker 3", "Patrick Tullos"], "start_timestamp": "25:12", "end_timestamp": "27:02", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "6fa9ccfb-95d4-427d-8bdd-d5b54e954811", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 13, "content": "Patrick Tullos (27:31): Yeah, it's really timely. It's something we're talking a lot about, and I think it kind of roots beyond mental health and just also into the inclusion and the reality that we as an outdoor industry have an inclusion problem and a diversity problem, obviously. But I think a lot of that is due to this aspirational marketing that is put out where if someone sees Alex Honnold, free soloing el cap, climbing just seems like a circus trick at that point where in reality, you can go out and climb five fun and just have a blast as a kid. I think there's a time and place for both, absolutely. But especially if we as people within the outdoor world want to expand and open our arms and show different groups of people how amazing the outdoor activities can be, I think we have to be honest with ourselves about what are we showing in our advertising and what messaging are we telling people to? (28:41): And I think it's really, really important. And then there's the other side of if you're an athlete and you're seeing, I mean, athletes are just insane right now, whether no matter what activity, what sport, if you're a mountain biker and you're watching Rampage, or we just put out a new video called Wild West, and some of the tricks on there is just next level, and the progression is just so more and more and more bigger, longer, faster, more flips, more spins of higher climbs, higher grades, and at some level as an athlete, that pressure has got to be immense. And the pressure, I think brands need to look at the pressure that they're putting on those athletes to get out and do dangerous things. And I think the other side of that is that the people that are going to be out doing those dangerous things, they do that because that's in their blood. But I think brands do have some level of responsibility to one, show consumers that outdoors can be accessible through their marketing, and two showcase athletes in a way that doesn't pressure them to do these things and gives them time to plan and do them the right way as well,\n\nSpeaker 3 (29:57): Because", "token_estimate": 523, "speakers": ["Patrick Tullos", "Speaker 3"], "start_timestamp": "27:31", "end_timestamp": "29:57", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "31a32a23-ff7f-4b17-b5d0-827bf6f6a377", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 14, "content": "Patrick Tullos (29:58): Mental health and the athletic spectrum is a huge issue as well. So yeah, that's a good topic.\n\nCole Heilborn (30:06): Yeah, no kidding. So what does that mean for Adidas, at least within the sports marketing division? How are these topics? How are you guys changing what you're doing? Are you changing what you're doing? How do you think about 'em?\n\nPatrick Tullos (30:20): It's something we're always looking at and how we utilize our partners. So whether it's a top tier athlete like Kevin Jorgenson or Timothy Olson on the trail running side, all the way down to a partner that we trust and is just as prolific in their activity in a different way. And there's different groups that we work with there, but I think a lot of it is just listening and supporting where we can, and then also making sure when we're are scouting for that next gen athlete, that we are helping coach those younger kids in a way that has longevity in mind in their careers, and also lets them know that we support them and we're signing them as partners of ours, and it's a two-way street. We have a responsibility to them just like their contract does to us. So yeah, I mean, I think it's complicated, and especially right now, we need to look at who we're talking to, what people were utilizing to talk to those people, and also just making sure that we're giving people the voice that can actually speak for that. I'm a white male, so how is it good for me to go out and just try to tell why you should buy this brand and why you should get behind this brand? It's more about listening and showcasing the voices that actually can make a difference too, and actually can pull people in that maybe wouldn't have even thought of outdoor activities as an opportunity. (32:17): So yeah.\n\nCole Heilborn (32:18): No, I love that. I mean, the world doesn't need more people telling other people what to do. We need more people to listen and encourage and\n\nPatrick Tullos (32:26): Support. Yeah, absolutely. Absolutely.", "token_estimate": 505, "speakers": ["Patrick Tullos", "Cole Heilborn"], "start_timestamp": "29:58", "end_timestamp": "32:26", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "5f61baa1-82b7-4753-b9b5-0efb595d1055", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 15, "content": "Cole Heilborn (32:29): Yeah. So coming back to I guess your journey over the last three years, what were some of the things, I mean, obviously I think people can draw the conclusion that getting outside, prioritizing that is a big influence on mental health. What were some of the other things that you had to make lifestyle changes around to start feeling better or feeling like your old self?\n\nPatrick Tullos (32:57): Yeah, probably the largest one is just doing this, what we're doing right now and just talking about it and normalizing it. Because I think when it comes to anxiety, at least part of the things as you close up and in order to let it out, that's how you release it. And it's so hard to let those things out if you don't have the ability or the opportunity to talk to someone. So for me, it was seeing a professional for sure, but it was also talking to friends and family and people I trust. And I had a couple of really solid mentors within the industry as well that really helped coach me through that time as well. (33:47): And then also medication, which is another huge, huge taboo topic to talk about. And I was deathly afraid to go on any sort of medication. Actually, the reason I kind of was okay with it was Conan O'Brien actually was talking about how he's on SSRIs, and I was like, wow, that is a trip that Conan O'Brien is. And it kind of made me feel like, okay, I'll try it. And honestly, it's changed my life. It just took a fog out that I didn't really know was there. And I don't know, I feel like there's a lot of people, and it's not the answer for everyone, but for me it definitely helped. And then all those other things I talked about too, obviously exercise is important, creating the time for yourself, meditation, healthy, eating, everything else, but those are probably the most important ones. The other ones don't. It's not like a magic pill or talking to someone will make you feel all better, but it's really a mix of all of that that just allows you to view things differently. And I think that's the most important part. It's never going to go away. It's more so about just shifting and experiencing and moving on.", "token_estimate": 542, "speakers": ["Cole Heilborn", "Patrick Tullos"], "start_timestamp": "32:29", "end_timestamp": "32:57", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "a05fcc60-7653-488a-96f9-b2d0aad23091", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 16, "content": "Cole Heilborn (35:12): And I think learning to be okay with yourself when it does happen too.\n\nPatrick Tullos (35:16): Oh, for sure. For sure. Yeah, absolutely.\n\nCole Heilborn (35:22): Does it seem weird thinking about yourself three years ago looking now and thinking about yourself having a conversation about mental health on the podcast that other people are going to listen to, I guess? What's that?\n\nPatrick Tullos (35:36): Yeah, it's still kind of weird to be honest. I mean, I think it's an exercise and it's something that you have to constantly do is be open and talk about uncomfortable things. And I think our society as a whole right now needs to talk about a lot of uncomfortable things. And this is a very small part of it, but it's also I think something that a lot of people are feeling right now, especially with the state of the world. I mean, we were joking before the podcast started, but what else could happen in 2020? But I think it's an important muscle to exercise of just continuing to talk about it. So yeah, I open the door to anyone who wants to reach out and just talk.\n\nCole Heilborn (36:24): That's great. And I think sometimes that's what people need is just someone in their circle who's made themselves available. And if you can break down that barrier, then someone who's struggling to talk to anyone will feel so much more welcomed\n\nSpeaker 3 (36:43): And\n\nCole Heilborn (36:43): They don't have to do as nearly as much work to talk to someone.\n\nPatrick Tullos (36:48): Right? Absolutely. Yeah. And everyone's different too, but for me, hearing other people say it was okay, helped so much to be able to take the first step, and especially in the competitive landscape of careers, you're always trying to be the most put together, and none of us are put together. We're all just trying to figure it out. So yeah, I think it's important, especially within the career space, that you can be successful and still have struggles as well.", "token_estimate": 493, "speakers": ["Cole Heilborn", "Patrick Tullos", "Speaker 3"], "start_timestamp": "35:12", "end_timestamp": "36:48", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "6e75a2ab-3870-4a10-bd83-386ffaae9faa", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 17, "content": "Cole Heilborn (37:30): Well said. So looking forwards, what's your hope on a few different levels? One, you personally, as you continue to move forwards and take on more challenges, but then two for Adidas and just the industry as a whole.\n\nPatrick Tullos (37:44): For me personally, I just want to continue doing fun stuff with my friends and building cool campaigns and building a brand too. I mean, that's what I'm so passionate about is just people and getting brand messaging out there and supporting the culture within all of our activities that we enjoy so much. And then from a brand point of view, we're just kind of just getting started here. Like I said, we're really only a year and a half in, so we have a lot of things coming down the pipeline. I think we have a really unique point of view being a part of a sporting goods brand, a larger sporting goods brand to pull a new audience into the outdoor space as well, which will be healthy for the whole outdoor industry too. So I'm just really excited, continue to showcase good content with amazing athletes and partners, and then also get a new audience viewing the things that we all know and love and know that can really change your life. Adidas has a saying internally that through sport we have the power to change lives, and whether you're down with a corporate jargon or whatever, we always talk in outdoor. It truly can. Outdoor sports I think are some of the most accessible in a lot of ways and can really change your life, at least for me personally and for a lot of people around me. I think it's proven fact.\n\nCole Heilborn (39:14): Well, especially when it comes with the support that Adidas has, because you look at some of the great commercials or campaigns over the last few decades, and there's been some amazing stuff that's come out of it, and it's because they've had a brand that has the support to pull that off. So if anyone does, you guys are definitely one of them.", "token_estimate": 489, "speakers": ["Cole Heilborn", "Patrick Tullos"], "start_timestamp": "37:30", "end_timestamp": "39:14", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "4740e68a-c5f3-4056-84f3-d19d8f3fa702", "episode_id": "38ade84a-8f35-41b7-a079-ea42bd0e4120", "cms_item_id": "68225dfc7bb476527f8c4845", "chunk_index": 18, "content": "Patrick Tullos (39:36): Yeah, yeah, definitely. And I think it's our job to just make sure that it's staying authentic buzzword, but it's staying authentic because yeah, that is one of the risks that as you get bigger and into bigger machines, not out of any ill will, but there's more people that can touch things. So I think that's our job within the business unit to just make sure that we're supporting the organizations and the athletes and the retailers and the people within the industry that are going to create the best voice for the industry as well, and the products and the sales will follow.\n\nCole Heilborn (40:16): Yeah. Well, we're just about out of time for today, but Patrick, thank you for sharing your story. I know some things aren't always easy to talk about. This certainly isn't one of 'em, but I thank you for doing that.\n\nPatrick Tullos (40:30): No, I had a blast. Thank you so much for the time. And honestly, I really enjoy talking about things like this, so find me if anybody's listening and would like to talk, I'm always down to talk to good people.\n\nCole Heilborn (40:44): Where can people find you?\n\nPatrick Tullos (40:48): I'm on Instagram at Patrick, the number two LOS, and then probably got to plug the brands too, so at Adidas TerraX and at five 10 as well. So you can check those out.\n\nCole Heilborn (41:02): Perfect. Well, thank you so much and have a good rest of your day and enjoy those donuts.\n\nPatrick Tullos (41:07): Yeah, I will for sure. Have a good one. We'll see you.\n\nCole Heilborn (41:10): All right. Bye bye. Thanks again for listening to this episode. If you enjoyed it, please consider sharing it with a friend or leaving us a review on Apple. Also, remember to check out Darby Communications. If you're looking for a great PR and marketing team, go ahead and find 'em at darby communications.com.", "token_estimate": 463, "speakers": ["Patrick Tullos", "Cole Heilborn"], "start_timestamp": "39:36", "end_timestamp": "41:10", "podcast_index": 34, "episode_name": "Ep 34: Patrick Tullos | Mental Health in the Outdoors | Adida‪s‬", "slug": "ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "web_url": "https://www.portsidepro.com/podcast-feed/ep-34-patrick-tullos-mental-health-in-the-outdoors-adidas", "guest_name": "Patrick Tullos", "guest_title": "Sr. Manager of Brand Communications and Sports Marketing, Adidas", "categories": [], "short_description": "\"For a long time I would say, ok I need to stop drinking caffeine, then I need to stop drinking alcohol, I need to exercise more, and it just wouldn't go away. Ultimately all of those lifestyle changes are good but they're like putting a band-aid on a shotgun wound.\"", "podcast_length": "44:56"}, {"id": "3470662b-5f0e-4ba0-9412-003c935936e2", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 0, "content": "Cole Heilborn (00:02): Welcome to the Backcountry Marketing Podcast. My name is Cole Hilborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial, and film production company based in the Pacific Northwest. Before we jump into today's episode, I wanted to talk about Darby Communications. They're our presenting sponsor for this episode. I've gotten to know them over the last few months as they've helped me with some PR and marketing for this podcast. The Darby Comm team has designed their process around my needs, combining a people first mindset with an analytical data-driven approach. (00:54): Today's business world moves fast, but the Darby Comm team has taken the time to truly get to know me and understand my goals. They've been a great partner to collaborate with, and I'm really impressed with their well-rounded approach that generate real results that actually help bring this podcast to more years. If you're in the market for a great PR team in the outdoor wellness and fitness industry, go ahead and check 'em out@darbycommunications.com. Welcome to the Backcountry Marketing Podcast. My name is Cole Hilborn. Today I'm sitting down with Maddie Petri, the director of Marketing of North America at Mammo. How are you?\n\nMaddie Petry (01:27): I am doing well, thanks. How are you doing?\n\nCole Heilborn (01:29): Doing great. Where are you joining us from?\n\nMaddie Petry (01:32): I am at my home office in Boulder, Colorado.\n\nCole Heilborn (01:36): Nice. Within the last few months, have you made changes to your home office? Have you made it a little more homey or upgraded it?", "token_estimate": 495, "speakers": ["Cole Heilborn", "Maddie Petry"], "start_timestamp": "00:02", "end_timestamp": "01:36", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "b40dbe3d-609b-4e34-abac-24289903d8cc", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 1, "content": "Maddie Petry (01:44): Yeah, it's been interesting. So my husband's a professional mountain biker and generally always home if he's not training. And so at first we had a little station right next to each other and quickly realized that was not going to work for us for both the professional and our marriage side of things. So yeah, I was booted to the basement real fast.\n\nCole Heilborn (02:08): That's probably best for everyone, I suppose. Yeah,\n\nMaddie Petry (02:11): Exactly. I can be as loud as I want now.\n\nCole Heilborn (02:15): Well, no, I'm glad you guys are hanging in there. I suppose for him though, he can just, for his work, he can just take off and go on a ride. I mean, I guess you could do the same thing, but it's a little easier for him. I got to imagine.\n\nMaddie Petry (02:25): It's definitely easier for him, and that's generally what happens. I'm like, okay, out you go.\n\nCole Heilborn (02:32): Well, I'm excited to be chatting today. Before we jump into the episode, I'd love to know more kind of about your role, what the director of marketing entails if, can you kind of paint us a picture, what your day-to-day looks like?\n\nMaddie Petry (02:47): Yeah, so I'm responsible for leading the vision and the strategy for Mout in North America, in the North American markets. So integrating our global marketing initiatives and working with our global teams to create relevant campaigns to support our sell through and brand awareness basically at every sector. So that's my day to day, and it's a small team, so really A to Z from creating the strategy to connecting with our partners, to working with the sales team to make sure that the stories we're telling about the product is hitting the market in the right ways.\n\nCole Heilborn (03:24): Okay. Right on. And that's got to be fun too, working at a brand. You guys are how old?\n\nMaddie Petry (03:30): Just over 158 years.\n\nCole Heilborn (03:33): Oh, man. That's so cool. And you guys, it's originally a Swiss brand, correct?\n\nMaddie Petry (03:38): It is a Swiss brand, yep. Still located in Switzerland as", "token_estimate": 520, "speakers": ["Maddie Petry", "Cole Heilborn"], "start_timestamp": "01:44", "end_timestamp": "03:38", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "3291e642-e1b9-40c2-b4c5-5129da919226", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 2, "content": "Cole Heilborn (03:41): Well. Okay, okay. I mean, you obviously haven't been with them for 158 years, but what's the history of the brand? Can you give us a little bit of the backstory?\n\nMaddie Petry (03:51): Yeah. So Mammo originally started with a man named Casper Tanner, and he had just finished a rope apprentices and really fell in love with it and decided that he was going to make ropes for a living and kind of branched out on his own. It really started being a family business and the creation of the first glacier rope. So that's really where our history kicks off in Switzerland. And from there, we've really expanded into these other areas of ski, hike, mountain mirroring, avalanche safety in addition to continuing to innovate in our climbing sector. But yeah, it's been family owned for a long time and really valued what we had learned for over 160 years and kind of took that history and expanded on it for the last century.\n\nCole Heilborn (04:45): Okay.\n\nMaddie Petry (04:46): It's been a run.\n\nCole Heilborn (04:47): I've always been really curious about the story with your guys' logo and your name, how did that come about?\n\nMaddie Petry (04:53): Yeah, so it wasn't right away that Mout had the name and the logo, but coming from Switzerland and having this history of being in the glaciers, the mammoth really stood for a sign of strength and perseverance. And so mammo of came from that word, from the mammoth and something that had had this history of being a strong mountain presence. And so they decided to name it mammo, the logo became the mammoth, and it's been that way ever since.\n\nCole Heilborn (05:28): So how did you end up with the company? What's your background?", "token_estimate": 425, "speakers": ["Cole Heilborn", "Maddie Petry"], "start_timestamp": "03:41", "end_timestamp": "05:28", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "2cf1c10e-f4fb-490d-8159-7c1ca2df90a0", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 3, "content": "Maddie Petry (05:31): So I come from a ski background, have competed in ski for quite a long time and found myself kind of bouncing around. I finished college and was a first grade teacher for a little bit, and then taught preschool art and decided that education was not going to be my route after teaching preschool art and really had long to get back into the industry for me when I was competing, I wouldn't say I was the most competitive athlete. It wasn't really about winning or doing well, and while that was an important part of what I did, it wasn't what really excited me about being in the industry. And so I had an opportunity to work with a lot of different brands, really great team managers who kind of brought me into their fold and taught me what it looked like to be on the brand side, all the different areas and hats that you had to wear and things you had to think about while also kind of tapping that creative side. (06:37): And that's what really kind of sparked my love and my passion for the outdoor industry as a whole. And after teaching, I just realized that that's where my heart was, and that's the place that I wanted to be. So I went back into the industry and got some really great advice from those people who had mentored me from the beginning to really dive in and try to expand my knowledge into as many areas as I could. Just learn whatever you could about every sector of the company from customer service to operations, to marketing, and understand the processes to making a brand come to life for the consumer. And so that's what I did. And I started in retail. I wrote for the ski channel for a little bit. I did social media, and then I had an opportunity to move to Spider, which was a very history ski brand, especially ski racing space. So yeah, so started there a couple years later, and then again had an opportunity within the marketing umbrella to try my hand at a lot of different areas, social media, digital marketing, eventually leading to the creation of their, or I guess the recreation of their free ski brand and being able to head up that project for them.\n\nSpeaker 3 (08:03): Okay.", "token_estimate": 536, "speakers": ["Maddie Petry", "Speaker 3"], "start_timestamp": "05:31", "end_timestamp": "08:03", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "a7da7e74-d7f7-4930-93b3-05f6b9c628e1", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 4, "content": "Maddie Petry (08:04): Yeah, so that's how I got back into it, and my time had come there. And Mammo was a company that I've had my eye on for a long time, especially in the avalanche safety. It really resonated with me as an outdoor enthusiast, as a participant of these sports. I really connected on a personal level to the brand and was excited to be part of their North American team and be able to really take this brand to the next level from the North American side. So yeah, here I am today.\n\nCole Heilborn (08:41): Very cool. And I think you have a really exciting opportunity. You're talking about taking the brain to the next level, especially in today's climate where there's so many people that are entering the sport who, or I should say not the sport, but are just entering outdoor activities either for the first time or are getting back into it, whether it's because they're, I dunno, tired of being at home or the things they used to want to go do you can't do because of the world state right now, and there's so many people that are getting back into running and mountain biking and cycling, and I'm assuming we're going to see the same thing with skiing this year. What is your observation with the trends that are happening in the last six months?", "token_estimate": 317, "speakers": ["Maddie Petry", "Cole Heilborn"], "start_timestamp": "08:04", "end_timestamp": "08:41", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "6a1b7392-a0e5-4472-9e5c-dcaf29bc5b12", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 5, "content": "Maddie Petry (09:27): Yeah, I think it's such a great opportunity for people to, like you said, kind of be reintroduced into the outdoors and what that looks like for 'em, whether it's people who have never partaked in it and now suddenly have more time on their hands. Commuting's not as big of an issue anymore. Work hours are changing the work from home and the life balance is changing. And so they're either getting into it for the first time, or we've seen a lot of people have more time to take a step back and say, Hey, these are the things that I want to prioritize in my life, and these are things I've always wanted to try and do, but I've never either taken that step or had the time to do that. And so we're seeing this trend of this influx, especially as we approach summer in the hike categories specifically. (10:20): But now, yeah, again, in the ski and the back country markets of saying, this is something I've always wanted to do. I'm working from home. I have a little bit more flexibility, a little bit more time, and now's my opportunity to step into it and really take that next step into something that I've always wanted to try or do. And so we're definitely seeing that shift. And I think it's very interesting because once you start doing those things, it's hard to go back once you start having this lifestyle of like, oh, I really enjoy hiking after work. This is something that's becoming part of my routine. It's really hard to go back to,\n\nSpeaker 3 (11:00): Oh,\n\nMaddie Petry (11:02): All these other things come first. And so I think it's a trend that's going to stick around for a long time.\n\nCole Heilborn (11:08): Well, in the bike world, there's a formula n plus one, and it means however many bikes you have, you always need to be adding one more. I think that could be applied to outdoor sports. As soon as you start hiking, then you're like, well, shoot, maybe I should start trail running. And then you're like, well, maybe I should start mountain biking and then road biking. And then it just kind of perpetuates", "token_estimate": 514, "speakers": ["Maddie Petry", "Speaker 3", "Cole Heilborn"], "start_timestamp": "09:27", "end_timestamp": "11:08", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "85b3059c-6394-408e-9928-781586db9390", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 6, "content": "Maddie Petry (11:29): The classic problem where you have too much gear and no garage. But I think, yeah, as you start to try these things, it opens up your horizon to this whole new world, and you see people doing these activities and you want to be a part of it once you kind get a little taste your hook.\n\nCole Heilborn (11:46): So what does this mean for Mamu? What are you guys thinking about? What are you doing with influx of people entering into the industry?\n\nMaddie Petry (11:58): Yeah, it's been interesting timing for us. Last year was a pretty critical year for us to take a step back and look at how we were speaking to our community and through what messages and what product when we marketed that product and saying, who do we really want to reach and how do we want to reach them? And what we learned was, well, safety has always been a large part of who we are. We weren't necessarily relaying that messages in ways that resonated with the community. (12:29): Talk a lot about, Hey, north America is such a big continent. We've got Canada, we've got North America. It's huge. The US is huge, and we really were sprinkling a lot of different messages across the entire us. And we said, okay, it's not really sticking in the ways that we want it to stick. And so part of being a brand that's going to move forward is saying, let's take a step back and set ourselves up for big growth opportunities and really start diving into what this community that has been huge brand evangelists for us want to see and what's important to them and what do they value while still tying back to who we are and what our mission is. And so we really reevaluated how we're coming to the market, and we decided that we were going to take a regionalized approach and really focus on the core of who we are, which is the safety messaging going back to the first glacier rope that actually held you on so you didn't die while you were not married. (13:36): And taking that message and saying, this is who we are. This is resonating with our consumers, and let's pull all the levers and turn this up in these areas. And so before COVID even hit, we were prepared to really have this influx of speaking to these consumers who were either heading to the outdoors for the first time and didn't understand what product they needed or we're yearning for a little bit more education to those people who have been our core market for a long time and saying, Hey, what is your message? Who are you guys? And how are you going to continue to speak to me in a way that's meaningful and resonates with me? And so we had a great opportunity to kind of, yeah, like I said, pull the levers and now we're at a spot where this stuff was already in place. The foundation was already in place to kind of hit the ground running and set up for what we hear will be one of the biggest backcountry seasons of all.", "token_estimate": 721, "speakers": ["Maddie Petry", "Cole Heilborn"], "start_timestamp": "11:29", "end_timestamp": "11:58", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "ed453b7f-3e33-4756-b46a-e4daec15d137", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 7, "content": "Cole Heilborn (14:35): Wow. So break that down a little bit more. You were saying you guys were kind of scattering messaging. What wasn't working about that and what have you revised to hopefully start working?\n\nMaddie Petry (14:48): Yeah, I think a lot of go through this, we kind of get in a state of, Hey, we need to be everything to everyone. And that's an easy trap to fall into. And I think that comes with a lot of different directions. The market's changing consistently. There's a lot of unknowns. And we said, okay, we can't be everything to everyone. That's not who we are. That's not who our brand is. So let's take a step back and really evaluate what's important to us, what aligns with our mission, what aligns with our values as a company and the goals that we want to accomplish, and how are we going to do that? And so instead of trying to spread our message across a product skew, we have 4,000 products in our categories and trying to spread that across all of North America, we said, okay, what are the products that make the most sense for the consumers that again, are our most influential consumers, the people that are true brand evangelists that are helping us craft this message for us, (15:47): And where do they play in these places? How do they play and how do we start to reach them? So we really took our marketing a step back and we said, okay, we're going to focus on these two markets. So for mammo, it's Colorado and Western Canada, and we're going to really speak to these consumers in a way that's going to have continual touch points in their communities. So they understand who we are, they understand the products that we're making, we're going to consistently innovate upon so that they can achieve what they want to achieve in whatever outdoor activity they want to do. And then we're going to introduce new products that make sense for them to help them achieve those goals. And so yeah, taking it from a giant objective down to a more focused objective and saying, these are the people that move our brand and these are the people that we need to be speaking to in a consistent and I relevant way.", "token_estimate": 536, "speakers": ["Cole Heilborn", "Maddie Petry"], "start_timestamp": "14:35", "end_timestamp": "14:48", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "89f79636-ff67-4416-b1cf-9f343e329741", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 8, "content": "Cole Heilborn (16:50): Yeah, yeah. Interesting. So it sounds like in order to unlock that you had to do two things. You had to, one, understand who the brand was, and then two, understand who your consumers were or who the consumers you wanted to target were. Was that challenging to work through both of those fronts?\n\nMaddie Petry (17:13): I think the challenge is really playing a long game. It's easy for brands to really think, I have to see quick results. This has to happen right away. But for us, it was a process of creating a space for our community to come to us and listening and learning as marketers instead of always saying, this is who we are, this is how we want to do it, this is how you need to play, this is how you need to wear our gear. Allowing for that space of learning about our consumers and what's important to them and what they value, and kind of marrying that process of learning while also marketing into a way that was going to create growth for Mout. And I think it's always scary to take a step back and say, Hey, we need to look at this from a smaller scale, a more impactful scale to set up for long-term growth in the future. And so it's something where we had to really say, okay, trust the process. Know that the efforts we put in now, the ROI might not come for another two years, another five years, but we're setting up that foundation so that we can be successful in these areas in the future.\n\nCole Heilborn (18:27): Interesting. So when it comes to your consumers, these consumers that you've identified, how did you identify that these are the people you're targeting? Are they just kind of like the core evangelists and you've been able to build out profiles around them?", "token_estimate": 430, "speakers": ["Cole Heilborn", "Maddie Petry"], "start_timestamp": "16:50", "end_timestamp": "18:27", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "7e914f5d-500d-4f75-b3b1-b6adbe8608ed", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 9, "content": "Maddie Petry (18:43): Yeah, I think it's a little bit of everything. So taking a deep dive into the data that we've had historically, who has bought our product, what's their demographic look like, to partnering up with people, like an expert voice where the platform helps you identify your professional group, your retail group, give you some insight there to continuing to do focus groups with the people that have purchased our product, and then really looking at new ways to bring in what we like to call newcomers. So it's important to kind of have that balance of speaking to both the native and the new. Did that answer that question?\n\nCole Heilborn (19:26): I think so, yeah. I think what I'm trying to understand is who are the people and what's the blend between this new wave of people and the hardcore group that's already sold on the brand?", "token_estimate": 214, "speakers": ["Maddie Petry", "Cole Heilborn"], "start_timestamp": "18:43", "end_timestamp": "19:26", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "4ae5c55e-294f-40f3-8dcd-9d094539a83d", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 10, "content": "Maddie Petry (19:41): So for us specifically in North America, we've done a really good job of speaking to the core group. The people that are at the top of the mountain, the people that are very experienced, they know the product, they've been on the product for years and years, they trust the product. I think where our challenge is is being at the top of the mountain and coming down the mountain to speak to those people who are just getting into these sports. A lot of times they use the bike analogy. If you're going out and doing an Ironman for the first time, you're not going to buy a $15,000 bike, you're going to buy a bike that you can test out, see if you like it, and then you move up your bike, whatever you want to call it, you move up in the tiers of getting a better bike, having the carbon wheels, whatever it looks like. (20:36): And so what we had to do was come off this expert level of the top of the mountain, come down the mountain a little and say, Hey, the education that we do with these experts, the focus that we put in allowing them to be part of our brand, the conversations we have, we have to also have it with these people who are just starting to get into the sports and then funnel them up through those tiers. And so it's been kind of a balancing act of what are the campaigns, the initiatives, and how are we speaking to these consumers that's going to hit both those newcomers and those natives and be meaningful to them? And a lot of that is the education part of it. How do we educate these new consumers on products that's going to really help them achieve their goals? And how are we going to educate these experts on product that's going to help them achieve their goals and marrying the two together?\n\nCole Heilborn (21:36): Yeah. You're speaking to two very different camps there. You're speaking to Camp five and base camp. How do you craft the messaging, or how do you engage both of those groups in equal ways or maybe not equal, but in the ways that they need to be spoken to?", "token_estimate": 507, "speakers": ["Maddie Petry", "Cole Heilborn"], "start_timestamp": "19:41", "end_timestamp": "21:36", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "b630b8b8-342c-4de6-bc81-1353c24752f9", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 11, "content": "Maddie Petry (21:54): Yeah, I think it's, again, coming back to who you are as a brand and what you value. And something for us that's been consistent for the last almost 160 years is this message of safety. And so we really leaned into that this year saying safety is something important to everyone. Now how we talk about it is going to be different for these people just for starting out in the industry and the people that are experts. It's something that is a red thread throughout all sectors of our marketing initiatives and how we speak to people. And so we'll take a group, for example, this past year, what was important to us is to reach those newcomers through a way that wasn't super intimidating. We partner with organizations like an aie, like an A MGA, providing these classes that can somewhat inhibit somebody from wanting to be in the outdoors because they're scared that they may not have the skills, they may not have the comfort level, they may not have the knowledge. And so we said, okay, let's take this group of people and talk about safety in a way that just gives them a little bit of a teaser into what a bigger class can look like. We still want to push people towards getting that education from the professional group, but if they have a little bit of knowledge in this area, then they'll most likely feel more comfortable going into a class, having just those little bit of tidbits that they can take with them and (23:22): Understanding what the community looks like. This is a place where people want to teach you. They want to make sure that you're comfortable in the outdoors. And especially from a brand side, we want to make sure that everything we're doing on our end makes you confident going into that space. And so that's one area where we touched on, whereas we work with the professional groups on safety and we have an avalanche program manager who's going deep into multi burials and what that looks like and how our equipment is really designed to make sure that you're doing your job the best you can as fast as you can. And so really finding that balancing act, but staying true to who we are at the core of our brand.", "token_estimate": 542, "speakers": ["Maddie Petry"], "start_timestamp": "21:54", "end_timestamp": "21:54", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}, {"id": "1302ad87-d7f4-478e-a63d-833ec14d1045", "episode_id": "2255f9f3-9efa-4df1-8fab-364a54c4bc69", "cms_item_id": "68225dfc7bb476527f8c4846", "chunk_index": 12, "content": "Cole Heilborn (24:08): Yeah, that's interesting. I feel like that could be perceived as kind of risky. What you're describing is you've taken, I guess to simplify it, you've taken North America messaging, stripped all of it, it sounds like, focused it in on these two regions, Colorado, Western Canada, and then within that you focused it down on the newcomers and the experienced people. Was there any concern that wouldn't pay off in the long run?\n\nMaddie Petry (24:37): Yeah, I think there's always that concern. And something that I have personally learned throughout my career is if you're not pushing the needle, you're not learning and you're not growing. And so while it seems like, okay, we're taking it down, but it's still a big bite to chew off, it's saying, okay, we're confident in the risks that we're taking. We're making these educated decisions to reach these consumers. And as a marketer, I feel like it's your job to kind of push that line a little bit and learn from it either way. I talk a lot with our team about we have to move the needle either way, and whether it's backwards, then at least it's a growth opportunity. And as a marketer, you have to be two parts creative, one part data driven, and you say, okay, I'm going to make the best decisions with what I have, but I also need to kind of push that line a little bit so that we can set ourselves up for growth and we can move into these new territories and we can speak to these new consumers.\n\nCole Heilborn (25:47): I think that makes a lot of sense, and especially in the outdoor space where there's lots of competition, and let's be honest, that extends to every industry, so many businesses serving the same industries. I think one of the things that differentiates companies is those that niche down and focus on whatever it is they focus on. I guess I don't have a question there other than I'm just curious what your thoughts are on brands focusing in on specific niches.", "token_estimate": 491, "speakers": ["Cole Heilborn", "Maddie Petry"], "start_timestamp": "24:08", "end_timestamp": "25:47", "podcast_index": 35, "episode_name": "Ep 35: Maddie Petry | Down the Mountain | Mammu‪t‬", "slug": "ep-35-maddie-petry-down-the-mountain-mammut", "web_url": "https://www.portsidepro.com/podcast-feed/ep-35-maddie-petry-down-the-mountain-mammut", "guest_name": "Maddie Petry is the Marketing Director", "guest_title": "Mareting Director, North America, Mammut", "categories": [], "short_description": "\"I think the challenge is playing the long game. It's easy for brands to really think [short term]. For us, it was a process of creating a space for our community to come to us.\"", "podcast_length": "44:57"}]
